Medic.internal.newLifeQuestFixTranslations = {
    ["Dakoi^M"] = "Дакой^M",
    ["Uruk^M"] = "Урук^M",
    ["Stirk Fellowship Soldier^m"] = "Солдат Братства Стирка^m",
    ["Stirk Fellowship Mage^f"] = "Маг Братства Стирка^f",
    ["Coldharbour Void-Shade^f"] = "Пустотная тень из Хладной Гавани^f",
    ["Statue^m"] = "Статуя^m",
    ["Statue^f"] = "Статуя^f",
    ["Applies to Mages' Fury, Endless Fury, and Mages' Wrath. Select in Skills menu."] = "Действует на способности «Ярость магов», «Безграничная ярость» и «Гнев магов». Можно выбрать в меню навыков.",
    ["Applies to Dark Exchange, Dark Conversion, and Dark Deal. Select in Skills menu."] = "Действует на способности «Темная сделка», «Темный обмен» и «Темный союз». Можно выбрать в меню навыков.",
    ["Applies to Siphoning Strikes, Leeching Strikes, and Siphoning Attacks. Select in Skills menu."] = "Действует на способности «Поглощающие удары», «Вытягивающие удары» и «Поглощающие атаки». Можно выбрать в меню навыков.",
    ["Applies to Strife, Funnel Health, and Swallow Soul. Select in Skills menu."] = "Действует на способности «Раздор», «Разделение жизни» и «Поглощение души». Можно выбрать в меню навыков.",
    ["Magma Armor, Azure Blue"] = "Броня из лавы (лазурно-голубая)",
    ["Applies to Magma Armor, Corrosive Armor, and Magma Shell. Select in Skills menu."] = "Действует на способности «Броня из лавы», «Разъедающая броня» и «Панцирь из лавы». Можно выбрать в меню навыков.",
    ["Molten Weapons, Azure Blue"] = "Лавовое оружие (лазурно-голубое)",
    ["Applies to Molten Weapons, Igneous Weapons, and Molten Armaments. Select in Skills menu."] = "Действует на способности «Лавовое оружие», «Вулканическое оружие» и «Лавовый арсенал». Можно выбрать в меню навыков.",
    ["Applies to Arrow Spray, Acid Spray, and Bombard. Select in Skills menu."] = "Действует на способности «Веер стрел», «Ядовитые стрелы» и «Яростный обстрел». Можно выбрать в меню навыков.",
    ["Applies to Twin Slashes, Blood Craze, and Rending Slashes. Select in Skills menu."] = "Действует на способности «Двойной порез», «Кровавое исступление» и «Рассекающий порез». Можно выбрать в меню навыков.",
    ["Crate Topper, Moons Over Orsinium"] = "Crate Topper, Moons Over Orsinium, бонус к ящикам, луны над Орсиниумом",
    ["Applies to Healing Seed, Budding Seeds, and Corrupting Pollen. Select in Skills menu."] = "Действует на способности «Целебные семена», «Пророщенные семена» и «Вредоносная пыльца». Можно выбрать в меню навыков.",
    ["Applies to Cleansing Ritual, Extended Ritual, and Ritual of Retribution. Select in Skills menu."] = "Действует на способности «Очищающий ритуал», «Продленный ритуал» и «Ритуал возмездия». Можно выбрать в меню навыков.",
    ["Applies to Grim Focus, Merciless Resolve, and Relentless Focus. Select in Skills menu."] = "Действует на способности «Мрачная сосредоточенность», «Безжалостная решимость» и «Непреклонная сосредоточенность». Можно выбрать в меню навыков.",
    ["Applies to Frost Cloak, Expansive Frost Cloak, and Ice Fortress. Select in Skills menu."] = "Действует на способности «Морозный плащ», «Широкий морозный плащ» и «Ледяная крепость». Можно выбрать в меню навыков.",
    ["Applies to Fatecarver, Exhausting Fatecarver, and Pragmatic Fatecarver. Select in Skills menu."] = "Действует на способности «Резчик судеб», «Ослабляющий резчик судеб» и «Прагматичный резчик судеб». Можно выбрать в меню навыков.",
    ["Applies to Snipe, Focused Aim, and Lethal Arrow. Select in Skills menu."] = "Действует на способности «Точный выстрел», «Прицельный выстрел» и «Смертоносная стрела». Можно выбрать в меню навыков.",
    ["Applies to Radiant Destruction, Radiant Glory, and Radiant Oppression. Select in Skills menu."] = "Действует на способности «Блистательное разрушение», «Блистательная слава» и «Блистательное подавление». Можно выбрать в меню навыков.",
    ["Applies to Puncturing Strikes, Biting Jabs, and Puncturing Sweep. Select in Skills menu."] = "Действует на способности «Пробивающие удары», «Пронзающие тычки» и «Пробивающий замах». Можно выбрать в меню навыков.",
    ["Applies to Bone Armor, Beckoning Armor, and Summoner's Armor. Select in Skills menu."] = "Действует на способности «Костяная броня», «Манящая броня» и «Броня призывателя». Можно выбрать в меню навыков.",
    ["Applies to Render Flesh, Blood Sacrifice, and Resistant Flesh. Select in Skills menu."] = "Действует на способности «Заживление плоти», «Кровавая жертва» и «Огрубевшая плоть». Можно выбрать в меню навыков.",
    ["Applies to Abyssal Impact, Cephaliarch's Flail, and Tentacular Dread. Select in Skills menu."] = "Действует на способности «Удар бездны», «Бич цефалиарха» и «Ужасное щупальце». Можно выбрать в меню навыков.",
    ["Applies to Runespite Ward, Impervious Runeward, and Spiteward of the Lucid Mind. Select in Skills menu."] = "Действует на способности «Щит рунной злобы», «Непроницаемый рунный щит» и «Оберег ясного ума». Можно выбрать в меню навыков.",
    ["Applies to Soul Trap, Consuming Trap, and Soul-Splitting Trap. Select in Skills menu."] = "Действует на способности «Захват душ», «Поглощающий захват» и «Расщепляющий захват душ». Можно выбрать в меню навыков.",
    ["A small clay statuette in the shape of a bat, painted with red polish.\n\nThe first of three components required to create the Roseblood Bat."] = "Маленькая глиняная статуэтка в виде летучей мыши, покрытая красным лаком.\n\nПервый из трех компонентов, необходимых для создания летучей мыши крови и роз.",
    ["Petals that fall from Sanguine's prized roses are not known to wilt, and are always slightly damp with blood.\n\nThe second of three components required to create the Roseblood Bat."] = "Как известно, лепестки, опадающие с драгоценных роз Сангвина, никогда не вянут и всегда слегка влажны от крови.\n\nВторой из трех компонентов, необходимых для создания летучей мыши крови и роз.",
    ["A deadly-sharp rose thorn from one of the myriad rosebushes that grow in Sanguine's eternal paradise. Watch your finger!\n\nThe last of three components required to create the Roseblood Bat."] = "Ужасно острый шип с одного из бесчисленных розовых кустов, растущих в вечном раю Сангвина. Берегите пальцы!\n\nПоследний из трех компонентов, необходимых для создания летучей мыши крови и роз.",
    ["In the halls of the Daedra, their crude mockeries of Tamrielic traditions extend to the courtesies of courtly dancing as well.\n\nA component required for the Roseblood Wings Recall customized action."] = "Жалкие попытки даэдра подражать тамриэльским обычаям распространяются и на изящное искусство придворных танцев.\n\nКомпонент, необходимый для настраиваемого действия — перемещения «Крылья крови и роз».",
    ["Darkly beautiful and ringed with bloody thorns, this fashionable accoutrement lures in dance partners while also pricking those who get too close.\n\nA component required for the Roseblood Wings Recall customized action."] = "Это зловещее и прекрасное украшение, окаймленное острыми шипами, манит к себе танцующих, но ранит тех, кто подойдет слишком близко.\n\nКомпонент, необходимый для настраиваемого действия — перемещения «Крылья крови и роз».",
    ["Victims of this deadly poison are found with reddened lips; the mark of one last dalliance with forbidden romance.\n\nA component required for the Roseblood Wings Recall customized action."] = "У жертв этого смертоносного яда алеют губы, выдавая последний миг, проведенный в запретной страсти.\n\nКомпонент, необходимый для настраиваемого действия — перемещения «Крылья крови и роз».",
    ["Wardrobe,Costume,Wardrobe,Disguise,Covering,Clothes,Gear,Wear,Worn,Apparel"] = "Wardrobe,Costume,Wardrobe,Disguise,Covering,Clothes,Gear,Wear,Worn,Apparel, гардероб, костюм, облик, маскировка, снаряжение, одежда, одеяние",
    ["Go on with Jeetra. These death-dancers seem to be quite capable! I'm not sure I totally trust the name, though.\n\nAnd don't worry about me. I'll be fine. Just need to clear my head. And … thanks for earlier. Gave me a lot to think about."] = "Поговори с Джитрой. Эти танцующие со смертью свое дело знают! Хотя от их названия мне не по себе.\n\nА за меня не переживай. Все будет хорошо. Мне просто нужно собраться с мыслями. Кстати, спасибо за тот разговор. Он заставил меня многое переосмыслить.",
    ["I have to ask—was it fun being a giant statue and stepping on cultists? Because it looked like fun from where I was standing.\n\nAnyway, now that we're here, what's next?"] = "Признайся, весело, наверное, было ходить в виде огромной статуи и давить культистов? Со стороны именно так и казалось.\n\nНу ладно, мы на месте. Что делаем дальше?",
    ["What a waste, and all because a lector got greedy. We can rebuild the lodge, but the lives lost … those are gone forever.\n\nStill, it would have been worse if you hadn't shown up. Thanks."] = "Такие потери… и все из-за жадности одного лектора! Штаб мы восстановим, а вот погибших уже не вернуть.\n\nНо если б ты не <<player{пришел/пришла}>> нам на выручку, было бы еще хуже! Спасибо тебе.",
    ["Latanwen took a fire bolt meant for me. If I can't get her out of here, I'll never forgive myself.\n\nBut who are you, stranger? You don't look like a cultist, and you're certainly not part of the college. What are you doing here?"] = "Латанвен приняла на себя огненную стрелу, летевшую в меня. Если я не вытащу ее отсюда, то никогда себя не прощу!\n\nНо кто ты, <<player{незнакомец/незнакомка}>>? На <<player{культиста/культистку}>> ты не <<player{похож/похожа}>>, но ты явно не из наших. Как ты здесь <<player{оказался/оказалась}>>?",
    ["May the Ancient Darkness guide your travels, friend. Perhaps I will see you again some dark night. I jest, I jest. I am a morning person.\n\nFeel free to examine my work. The ancient words of the death-dancers are fascinating!"] = "Да направит тебя в странствиях древняя тьма, <<player{друг/подруга}>>. Возможно, мы еще увидимся темной ночью… Шучу. Я жаворонок.\n\nЕсли хочешь, можешь ознакомиться с моей работой. Слова древних танцующих со смертью достойны восхищения!",
    ["Go get those components for the siege weapon, long-strider.\n\nOr do what Argie says. Suraj isn't your captain. Figure it out yourself! I'm trying to catch some fish. Someone's got to make sure this crew gets fed."] = "Иди, найди детали осадного орудия, длинные ноги.\n\nИли делай, как сказала Арги. Сурадж не твой капитан. Так что решай <<player{сам/сама}>>! А каджит попробует наловить рыбы. Кто-то же должен кормить команду.",
    ["Captain ordered me to stay here and protect the surviving crew.\n\nI would rather be out there doing what you're doing, but orders are orders."] = "Капитан велела мне оставаться здесь и защищать тех, кто уцелел.\n\nЯ бы лучше составил тебе компанию, но приказ есть приказ.",
    ["Don't mind Kauldin. Lector Fenworine's betrayal stung him like an angry netch. And after I was wounded and another apprentice fell, he's been extremely cautious.\n\nBut if you aren't with the Worm Cult, who are you?"] = "Не обижайся на Колдина. Предательство лектора Фенворин ударило по нему больней щупальца злого нетча. После того как меня ранили, а еще один ученик погиб, Колдин больше никому не доверяет.\n\nНо если ты не из культа Червя, то кто же ты?",
    ["Suraj said he wished we met you before all this. Thinks things would have been different for all of us.\n\nMaybe so. But I've never been one to look back in such a way. Makes my neck hurt."] = "Сурадж говорит, жаль, что мы не встретили тебя раньше. Тогда бы для нас все сложилось иначе.\n\nМожет, и так. Но я стараюсь не оглядываться назад — шея болит.",
    ["Fine job rousing those mutineers. Desa got here just before you. Quite the spitfire, isn't she? So long as she doesn't eat any of the others, or make a habit of mutiny, she'll make a fine addition to the crew.\n\nWell, are you ready?"] = "Ловко ты <<player{взбаламутил/взбаламутила}>> этих бунтовщиков. Деса появилась как раз перед тобой. Огонь, а не женщина. Нам как раз такие нужны. Главное, чтоб еще один бунт не подняла и остальных с толку не сбила.\n\nНу что, ты <<player{готов/готова}>>?",
    ["Suraj, you've met already. Argenta … requires a bit more patience. Which is why I asked you to speak to her first.\n\nGot no soul, but she's still got a good heart."] = "Сураджа ты уже знаешь. А вот Аргента… к ней нужен особый подход. Поэтому я и попросила тебя сначала поговорить с ней.\n\nДуши у нее нет, но сердце на месте.",
    ["I will aid you if I can, but this fight belongs to you and Darien. The rest of us cannot touch Mannimarco without the Light of Meridia to strengthen our blows."] = "Я помогу вам чем смогу, но эта битва принадлежит вам с Дарьеном. Мы не сможем даже коснуться Маннимарко: без Светоча Меридии наши удары не достигнут цели.",
    ["Those blighting cultists and their Daedra took my sister, Lienyl. We were so close to getting away! She wanted to start a new life outside of Coldharbour.\n\nInstead, we just landed in another nightmare."] = "Проклятые культисты и их даэдра забрали мою сестру, Лиэнил. Нам почти удалось сбежать! Она хотела начать новую жизнь за пределами Хладной Гавани.\n\nА вместо этого мы оказались в очередном кошмаре.",
    ["With all the Daedra, I did not expect to find Tindensea is still here. Perhaps she can help us find the old manuscripts Elder Tso-Nassa spoke of. I would hate to have to search through all these shelves without some guidance."] = "Не ожидала, что Тинденсея останется здесь, несмотря на нашествие даэдра. Возможно, она подскажет, где тут древние манускрипты, о которых говорил старейшина Цо-Насса. Не хотелось бы рыться на полках, не зная толком, где искать.",
    ["If you're done talking Darien out of his dark mood, I'm eager to hear your report. Jeetra explained about Vanus's note in the mine, but what happened at the soul flayer harvest sites? Skordo and Raz said you destroyed them, but not much else."] = "Если ты уже <<player{закончил/закончила}>> свои попытки развеселить Дарьена, то я жду твой доклад. Джитра сказала мне о записке Вануса в шахте, но что произошло на местах размещения? Скордо и Раз сказали только, что пожиратели душ уничтожены.",
    ["Captain One-Eye said you mean to give a speech. Didn't have those back at the Caterwaul. Curious what you have to say."] = "Капитан Одноглазка сказала, что ты хочешь произнести речь. На «Истошном вопле» ни разу ничего такого не было. Интересно будет послушать.",
    ["That's all I have to give to you! At least let me finish the job before I head back to Sunport and turn myself in. I do have a reputation to uphold."] = "Больше мне нечего тебе дать! Позволь хотя бы закончить работу, прежде чем я вернусь в Санпорт и сдамся страже. Мне же нужно поддерживать репутацию.",
    ["You get one warning, stranger. I bite. And if you stick around too long, Captain Velehk Sain will take you prisoner and make a meal out of your soul.\n\nNow, get lost before I decide to eat you first."] = "Дважды предупреждать не буду, <<player{незнакомец/незнакомка}>>. Я кусаюсь! Будешь тут торчать — капитан Велек Сейн возьмет тебя в плен и закусит твоей душой.\n\nПроваливай, пока я не передумала и не съела тебя сама.",
    ["That observer is on high alert. Someone must have seen you on your way here and raised the alarm.\n\nI just want to get out. If I'd known Captain Sain treats his crew as well as he treats his prisoners, I'd have just stayed a prisoner."] = "Тот наблюдатель настороже. Видно, кто-то заметил тебя по дороге и поднял тревогу.\n\nЯ просто хочу отсюда выбраться. Знай я, что с командой капитан Сейн обращается не лучше, чем с пленниками, — осталась бы в плену.",
    ["Seems like that observer has no idea you're here. You'd lose that advantage if one of us goes with you.\n\nI just want to get out. If I'd known Captain Sain treats his crew as well as he treats his prisoners, I'd have just stayed a prisoner."] = "Тот наблюдатель, похоже, не знает, что ты здесь. Но если кто-то из нас пойдет с тобой, ты потеряешь это преимущество.\n\nЯ просто хочу отсюда выбраться. Знай я, что с командой капитан Сейн обращается не лучше, чем с пленниками, — осталась бы в плену.",
    ["Not even a nibble from a small dhufish! I'll have better luck fishing in Shadowfen's fouls this New Life. \n\nMaybe I'll try reeling the fabled Dakoi fish that appears this season."] = "Даже мелкий жемчужный окунь ни разу не клюнул! Похоже, в этот Праздник Новой жизни мне скорее повезет с рыбалкой в сточных водах Тенетопи.\n\nМожет, попробую поймать легендарного дакоя, который объявился в этом году.",
    ["Oh, what fun we have at New Life! Did the Dragon's fire make your fur cringe, too? So exciting yet terrifying at the same time!\n\nBut tell me, friend. Did you complete the challenge of Rawl'kha's Dragon? Did you give the swiped coin to beggar Yarg?"] = "Ах, как же весело мы отмечаем Праздник Новой жизни! У тебя тоже шерсть встала дыбом от огня Дракона? Так захватывающе — и в то же время страшно!\n\nНо скажи мне, <<player{друг/подруга}>>, тебе удалось пройти испытание Дракона Рол’ки? Ты <<player{отдал/отдала}>> украденную монету нищему Яргу?",
    ["The lair of Rawl'kha's Dragon rests inside a nearby cavern. An Orc beggar named Yarg attempted to swipe a coin from the Dragon's hoard, but the traps proved to be too much for his aging tusks.\n\nSo you must sneak in and steal one for him!"] = "Логово Дракона Рол’ки находится в пещере неподалеку. Нищий орк по имени Ярг пытался украсть монету из его сокровищ, но ловушки оказались ему не по клыкам.\n\nТак что теперь твой черед прокрасться внутрь и украсть для него монету!",
    ["A traveler! Seeking a New Life festivity, perhaps? You surely appear equipped to face worthy adversaries, but are you as sly and quick enough to steal coin from Rawl'kha's Dragon?"] = "<<player{Путник/Путешественница}>>! Ты, верно, думаешь, как отметить Праздник Новой жизни? Несомненно, ты <<player{готов/готова}>> сразиться с достойными противниками, но достанет ли тебе хитрости и проворства, чтобы украсть монету у Дракона Рол’ки?",
    ["Nice work making it to the Dragon's hoard! Who would have thought I'd enjoy this game more than getting pounded by a vosh ball?\n\nNow, you're supposed to give me that coin …."] = "Лихо ты <<player{добрался/добралась}>> до сокровищ Дракона! Кто бы мог подумать, что эта игра доставит мне больше удовольствия, чем быть целью мяча для воша?\n\nТеперь тебе вроде как полагается отдать эту монету мне…",
    ["I'd ask you to be my partner, but you look like you have bigger ponds to fish in. \n\nSo long as that Dakoi still swims though, you have a place on my fishing boat."] = "Я попросил бы тебя стать <<player{моим напарником/моей напарницей}>>, но, похоже, тебя интересует куда более крупная рыба.\n\nИ все же, пока этот дакой где-то плавает, на моей рыбацкой лодке для тебя всегда найдется место.",
    ["Hmm. That smell. So you finally caught the Dakoi then?"] = "Хм. Этот запах… Неужели ты наконец <<player{поймал/поймала}>> дакоя?",
    ["The fish always gives me the slip in the streams near Stormhold's outskirts. It … also nipped all my bait.\n\nHmm. An abandoned Shadowscale camp west of here has bottles of special bait that might work. Look for Bloodwine. Trust me."] = "Эта рыба всегда ускользает от меня в ручьи близ Стормхолда. А еще этот гад сожрал всю мою наживку.\n\nХм. В заброшенном лагере Темных ящеров к западу отсюда есть бутылки с особой наживкой, которая может сработать. Поищи кровавое вино. Доверься мне.",
    ["Hmm. Did the others send you to me out of pity? Bah, it's pointless! I've chased that Dakoi long enough for it to know my every move. Maybe I do need a partner.\n\nAt least we'd share the embarrassment."] = "Хм. Кто-то прислал тебя ко мне из жалости? Ох, да какой в этом смысл? Я пытаюсь поймать дакоя так давно, что он уже изучил все мои приемы. Возможно, мне и правда нужен напарник.\n\nВ крайнем случае опозоримся вместе.",
    ["The sneaky, little Dakoi has never been this hard to wrangle! What sort of games is it playing this time for New Life?"] = "Никогда еще тягаться с пронырливым маленьким дакоем не было так трудно! Что он выкинет на Праздник Новой жизни в этом году?",
    ["Well, seems like Yesei finally learned to swallow his pride. And all it took was me getting covered in mud.\n\nI think someone else can don the Dakoi fins next New Life."] = "Что ж, похоже, Йесей наконец-то научился смирять свою гордость. Всего-то и нужно было, чтобы я вымазался в грязи.\n\nПускай на следующий Праздник Новой жизни плавники дакоя примерит кто-нибудь другой.",
    ["Fresh mud is all we need for the effigy to evoke his blessing. Once you collect enough, our ceremony will bring the Mudman to life! My kin loved this ritual so much.\n\nWe'll continue praying until your return."] = "Чтобы получить благословение Грязевика, нам нужна лишь свежая грязь. Набери побольше — и наша церемония вдохнет в него жизнь! Мои родные всегда любили этот ритуал.\n\nМы будем продолжать молиться, пока ты не вернешься.",
    ["Nice work! Just look at how content you made Garth. His mood has improved a thousandfold and New Life—indeed all of Tamriel—is safe for another season.\n\nI think."] = "Молодец! Смотри, какой у Гарта довольный вид. Его настроение улучшилось в тысячу раз, и теперь Новой жизни и Тамриэлю ничего не грозит целый год!\n\nНу, я так думаю.",
    ["Garth likes the honeycomb, but I always play him a tune at meal time. And now this juggling has me exhausted! \n\nYou need to do it, friend. Play Garth a tune and put him in a good mood before Tamriel and New Life are doomed!"] = "Гарт любит медовые соты, но я всегда что-нибудь играю ему во время трапезы. Вот только сейчас у меня уже сил никаких не осталось после жонглирования!\n\nЗаймись этим ты, <<player{друг/подруга}>>. Сыграй Гарту и подними ему настроение, иначе Тамриэль и Новая жизнь будут обречены!",
    ["Speak quickly, traveler. Garth's not in the best of moods, as you can plainly see. If I halt my performance for too long, he may decide I'd be better as his next meal than his entertainer. And then he'll turn his appetite on all of Tamriel!"] = "Говори быстрее, <<player{путник/путешественница}>>. Как видишь, Гарт не в духе. Если я прерву свое выступление надолго, он заскучает и решит меня съесть. А там и всему Тамриэлю несдобровать!",
    ["The other Skaals are as blind as a moth priest. The All-Maker speaks through Garth and his mood determines the fate of Tamriel!"] = "Остальные скаалы слепы, как жрецы Мотылька. Через Гарта говорит сам Все-Создатель, и от его настроения зависит судьба Тамриэля!",
    ["Once again, Alik'r's winds have brought us together. It's strange. I almost feel like someone else hidden in the sands is watching us.\n\nAnyway, it seems like I'll only be able to rely on you."] = "Ветра Алик’ра вновь привели тебя ко мне. Как странно… Будто кто-то, сокрытый в песках, наблюдает за нами.\n\nЧто ж, похоже, ты — моя единственная опора на этом пути.",
    ["Hello, friend! Care to hear about all the wonderful festivities taking place for the New Life Festival this season?"] = "Привет, <<player{друг/подруга}>>! Хочешь, расскажу, какие восхитительные празднества в честь Новой жизни ждут тебя в этом году?",
    ["I am astonished. Ghadaz hasn't performed that well in years. I should start writing letters. People need to see this play."] = "Я в восторге. Гхадаз так не блистал уже много лет. Пора начинать рассылать приглашения. Этот спектакль должны увидеть все!",
    ["Let's leave this horrible place of torment and blood so Terinvel and I can calm down. We can talk back at my campsite."] = "Давай покинем это ужасное, кровавое место, чтобы мы с Теринвелом могли успокоиться. Поговорим в моем лагере.",
    ["I was enjoying this batch, but as it says in the Tenets of the Black Worm, there's more victims where those came from.\n\nDark Adept Vairisse's rounds usually take her to the other side of that door about this time. You shouldn't keep her waiting."] = "Эта партия пленников доставила мне большое удовольствие, но в кодексе Черного Червя сказано: всегда можно найти новую жертву.\n\nВ это время суток темный адепт Вайрисса обычно подходит к этим дверям с другой стороны. Не заставляй ее ждать.",
    ["Traveler! Do not attack Sharadak! This one has captured the vile illusionist, Milie Reynaud, after chasing her across land and sea.\n\nShe is a very dangerous prisoner. If Sharadak is not careful, he may fall prey to another one of her vile tricks!"] = "<<player{Путник/Путешественница}>>! Не нападай на Шарадака! Каджит гонялся за подлой иллюзионисткой Мили Рейно по суше и по морю и наконец поймал ее.\n\nОна очень опасная пленница. Если Шарадак не будет осторожен, он может стать жертвой очередной ее гнусной выходки!",
    ["Traveler! Sharadak seeks a bounty for the vile illusionist, Milie Reynaud. She is a master of disguise. This one has chased her across land and sea.\n\nIf this one is not careful, he may fall prey to another one of her devious tricks."] = "<<player{Путник/Путешественница}>>! Шарадак пытается получить награду за подлую иллюзионистку Мили Рейно. Она мастер маскировки. Каджит гнался за ней по суше и по морю.\n\nЕсли каджит не будет осторожен, он может стать жертвой очередной ее коварной выходки.",
    ["You're not from in the Hall. I would recognize you. Which means you broke in somehow. Maybe through the rumored breaches in the walls?\n\nDon't fear that I'll hurt you, mortal. I just want to find a way out. I can't survive in this place."] = "Ты не из Зала. Я бы тебя узнала. Значит, ты как-то сюда <<player{пробрался/пробралась}>>. Может, через те самые бреши в стенах?\n\nНе бойся, <<player{смертный/смертная}>>, я не причиню тебе вреда. Я просто хочу найти выход. Я тут не выживу.",
    ["Of all the times for that silly hound to try to be a hero.\n\nNever realized how much I actually care about him."] = "И надо же было этому глупышу именно сейчас играть в героя…\n\nЯ и не осознавала, до чего сильно к нему привязалась.",
    ["Traveler! You are not with the Worm Cult, are you? I beg a moment of your time. I need someone to deliver a message to Healer Namreras at the Central Siege Camp.\n\nI need you to tell her that her husband, Tesamoril is … dead."] = "<<player{Путник/Путешественница}>>! Ты ведь не из культа Червя? Можно тебя на минутку? Мне нужно, чтобы кто-нибудь передал весть целительнице Намрерас в центральном осадном лагере.\n\nПожалуйста, скажи ей, что ее муж Тесаморил… погиб.",
    ["Dark Adept Vairisse is a stern commander who does not like to be kept waiting. Which is why we should probably have been faster extracting those souls."] = "Темный адепт Вайрисса — суровый командир, и ждать она не любит. Наверное, нам следовало извлечь души побыстрее.",
    ["Is it me or has Skordo gotten worse at holding his liquor?\n\nAnd you! Sit, sit. This has been a long time coming. I've promised you more drinks than I can count. Not sure I can afford to make good on all of them, but let's give it a try!"] = "Мне кажется или Скордо теперь пьянеет быстрее, чем раньше?\n\nА ты! Садись, садись. Мы этого давно ждали. Я уже столько раз обещал тебя угостить, что и не сосчитать. Вряд ли у меня на все хватит денег, но попробовать стоит!",
    ["I must return to the mainland and report all we've uncovered here. Just one more task to add to my already overburdened schedule.\n\nSolstice has been … eventful. I'd welcome a little peace, but peace rarely lingers for those such as us, doesn't it?"] = "Я должен вернуться на большую землю и сообщить обо всем, что мы тут узнали. Как будто мое расписание и без того недостаточно плотное.\n\nМое пребывание на Солстисе оказалось… весьма бурным. Я был бы не прочь отдохнуть, но таким, как мы, покой только снится, не так ли?",
    ["Oh, thank you so much! I would have been heartbroken if they didn't get something for New Life. Now, allow me to offer you my gratitude. I hope this helps you on your journeys ahead.\n\nReturn soon and we'll make another meal to offer for New Life!"] = "Огромное тебе спасибо! Если бы они остались на Праздник Новой жизни без подарков, у меня душа была бы не на месте. Позволь же мне тебя отблагодарить. Надеюсь, это пригодится тебе в странствиях.\n\nВозвращайся скорее, и мы приготовим еще что-нибудь в честь Новой жизни!",
    ["Talk to Lanullin"] = "Поговорить с Лануллин",
    ["I prepared the offering and delivered it to the elder."] = "Я <<player{приготовил/приготовила}>> дар и <<player{передал/передала}>> его старейшине.",
    ["Then Tibarr proclaims this New Life a success! Allow this one to reward you for your noble efforts. It's the least Tibarr can do for enduring his silly festivity.\n\nAnd Tibarr promises more if you brave his Dragon's lair again!"] = "В таком случае Тибарр объявляет, что Праздник Новой жизни удался! Позволь каджиту наградить тебя за великодушие. Это самое малое, чем Тибарр может отплатить за то, что ты <<player{пережил/пережила}>> его потешное празднество.\n\nА если ты отважишься отправиться в логово Дракона еще раз, Тибарр наградит тебя вновь!",
    ["Talk to Tibarr"] = "Поговорить с Тибарром",
    ["I gave the Dragon's coin to Yarg."] = "Я <<player{отдал/отдала}>> монету Дракона Яргу.",
    ["Not bad, traveler. Seeking help is usually a last resort for me, but perhaps I've been too hasty to try to accomplish everything by myself.\n\nThere's still more New Life to celebrate, so feel free to swing by the next time you wander this way."] = "Неплохо, <<player{путешественник/путешественница}>>. Обычно я редко прошу кого-то о помощи, но, пожалуй, я поторопился, пытаясь сделать все в одиночку.\n\nПразднование Новой жизни продолжается, так что не стесняйся — заглядывай в следующий раз, когда будешь проходить мимо.",
    ["Talk to Yesei"] = "Поговорить с Йесеем",
    ["Yes, I cornered your Dakoi, and he gave me this fish for you."] = "Да, я <<player{загнал/загнала}>> твоего дакоя в угол. И он дал мне для тебя вот эту рыбу.",
    ["Ah, just like my kin. Take this, along with Mudman's blessing. And you're welcome to return for more.\n\nThe Mudman must thrive through the entire New Life season. And, like all of life, it needs care."] = "Ты прямо как мои дети. Вот, прими это вместе с благословением Грязевика. И я буду рада, если ты вернешься.\n\nПока идет Праздник Новой жизни, Грязевик должен оставаться в наилучшей форме. И, как любому живому существу, ему нужна забота.",
    ["Talk to Dailonda"] = "Поговорить с Дайлондой",
    ["You mentioned a reward?"] = "Ты что-то говорила о награде.",
    ["Oh, you remember that, do you. Well, what the tusk, it's New Life! You earned the boon and more, and you finally gave me some true competition.\n\nCome back for another swing! Surely there's more Oblivion boulders where that one came from!"] = "Ишь ты, не <<player{забыл/забыла}>>… А, клык с ним, праздник все-таки! Да и ты это <<player{заслужил/заслужила}>> — давненько я не встречал серьезного соперника.\n\nПриходи еще! В Обливионе это наверняка был не последний валун!",
    ["Talk to Mahagog"] = "Поговорить с Махагогом",
    ["You mentioned you were going to throw in something extra, I believe."] = "Если не ошибаюсь, ты говорил, что накинешь сверху немного золотых.",
    ["As long as a piece of the All-Maker resides in Garth, his mood will always hang like a sharp blade over New Life. \n\nI'll continue to do my best to keep him entertained, but should you return I may call upon you again for assistance. Happy New Life!"] = "Пока в Гарте живет частица Все-Создателя, его настроение всегда будет угрожать Новой жизни.\n\nЯ постараюсь не дать ему снова заскучать, но, если ты вернешься, могу обратиться к тебе за помощью еще раз. С Праздником Новой жизни!",
    ["Talk to Baldan"] = "Поговорить с Балданом",
    ["You think?"] = "Ты так думаешь?",
    ["Indeed. However, centuries of resentment rests beneath these sands. Return if you can to help Yokuda's waters flow here. Another also approaches who may need your help, too.\n\nBefore I take my leave, here. From the Kogo-Hi."] = "Воистину. Однако эти пески скрывают многовековую неприязнь. Если сможешь вновь направить сюда воды Йокуды — возвращайся. Сюда уже идет еще одна путешественница, которой, возможно, потребуется твоя помощь.\n\nПрежде чем мы простимся, прими этот дар от кого-хи.",
    ["Talk to Hassavir"] = "Поговорить с Хассавиром",
    ["The ritual is complete then?"] = "Значит, ритуал завершен?",
    ["No … but it's like the winds guiding me carried thoughtful eyes, watching my every step. Perhaps it was the heat.\n\nBut I find every ritual helps me understand my own path. And I hope you'll join me again."] = "Нет… но ветра, что вели меня, как будто бы внимательно следили за каждым моим шагом. Наверное, это все жара.\n\nЯ заметила, что каждый ритуал помогает мне лучше осознать свой путь. Надеюсь, ты еще составишь мне компанию.",
    ["Talk to Jahesi"] = "Поговорить с Джахеси",
    ["Did you see someone on your journey?"] = "Ты видела еще кого-нибудь по дороге?",
    ["I regret that it has come to this. A fast moving vampiric change means that Terinvel is a danger to everyone. I must deal with it, as a friend should. \n\nI'm grateful for your steady support and calm demeanor through this. Here's payment as promised."] = "Мне жаль, что все так сложилось. Но Теринвел быстро превращается в вампира, а значит, становится опасен для окружающих. Я его друг — и я выполню свой долг.\n\nСпасибо тебе за поддержку и неизменное спокойствие. Вот оговоренная плата.",
    ["Why does the dark adept put up with that prince?"] = "И зачем темный адепт возится с тем принцем?",
    ["I do not know which warmth I cherish most. That of the sun's light, the burning coals of our nests, or that of my partner who no longer sleeps beside me. May they rest in stone and memory."] = "Не знаю, что могло бы согреть меня лучше: свет солнца, жар углей в наших гнездах или тепло моего партнера, который больше не спит со мной рядом. Пусть он покоится в камне и воспоминаниях.",
    ["First, I'll kill you. Then I'll see the end of Captain One-Eye."] = "Сначала я убью тебя. А потом прикончу капитана Одноглазку.",
    ["The Spriggan's going to be ferrying some well-paying passengers off Solstice. I recognize them from back home, but they haven't recognized me yet.\n\nStrange seeing Gahz and Oorbesh be so civil. And I'll be keeping an eye on their … friend."] = "Скоро «Спригган» увезет с Солстиса пассажирок, которые щедро заплатили за путешествие. Они обе с моей родины, но меня пока не признали.\n\nНепривычно видеть Газ и Орбеш такими вежливыми. А вот за их… дружком я буду присматривать.",
    ["When activated, plays the lively music box composition \"Grave-Stake Gambol.\""] = "При использовании воспроизводит оживленную композицию «Танец у могильных столбов».",
    ["Music Box, Grave-Stake Gambol"] = "Музыкальная шкатулка «Танец у могильных столбов»",
    ["Achievement Furnishings: Solstice"] = "Предметы обстановки за достижения: восточный Солстис",
    ["This small, well-stitched satchel contains a handful of Trade Bars."] = "这个缝制精美的包裹里装有一些交易金条。",
    ["Trade Bar Satchel"] = "装有交易金条的包裹",
    ["Grants an Outfit Style Collectible. Once used, the Outfit Style is available to all characters on your account. Outfit Styles can be used at an Outfit Station to customize your appearance."] = "Дает коллекционный предмет — стиль нарядов. После использования этот стиль станет доступен для всех персонажей вашей учетной записи. С помощью стилей можно менять свой внешний вид в мастерской нарядов.",
    ["Bound Style Page: Nokvroz's Greatsword Replica"] = "Привязанная страница стиля: Копия двуручного меча Ноквроза",
    ["Ashbound Hall"] = "Пепельный зал",
    ["Boss Room"] = "Комната с боссом",
    ["Amulet Area"] = "Область амулета",
    ["Dealing damage with a Bash or fully-charged Heavy Attack places the <<1>> on your target for <<2>>. While active, you gain <<3>>, increasing damage done by <<4>>, and deal <<5>> more damage to the target and <<6>> less damage to all other enemies. If the enemy dies while marked, you gain <<7>> Stamina or Magicka, based off your highest maximum resource. This effect can trigger up to every <<8>>."] = "Нанося урон прерывающим ударом или полностью заряженной силовой атакой, вы на <<2>> накладываете на противника <<acc:c:1>>. Пока она действует, вы получаете эффект «<<3>>», увеличивающий наносимый урон на <<4>>, а также наносите на <<5>> больше урона цели и на <<6>> меньше урона — всем остальным противникам. Если противник под действием метки погибает, вы восстанавливаете <<7>> ед. запаса сил или магии (в зависимости от того, запас какой из характеристик больше). Этот эффект может срабатывать не чаще чем раз в <<8>>",
    ["Quake"] = "Землетрясение",
    ["Stop"] = "Остановка",
    ["Remove"] = "Удаление",
    ["Visability"] = "Видимость",
    ["Mor Naril Priory"] = "Приорат Мор-Нарила",
    ["Note to Gabrielle"] = "Письмо для Габриэль",
    ["Search"] = "Обыскать",
    ["Dragon's Hoard"] = "Сокровища Дракона",
    ["Mark"] = "Сделать отметку",
    ["Garth's Feeding Stone"] = "Камень-кормушка Гарта",
    ["Bottle of Bloodwine"] = "Бутылка из-под кровавого вина",
    ["Destroy"] = "Уничтожить",
    ["Mural Dedication"] = "Посвящение фрески",
    ["Writhing Fortress"] = "Трепещущая крепость",
    ["Currency Vault"] = "Валютное хранилище",
    ["The currency vault dynamically shows the amount of gold you currently have. As you earn more gold, more shows up inside the vault. As you spend gold, less gold appears inside the vault."] = "Валютное хранилище динамически отображает количество золота, которым вы располагаете на данный момент. Чем больше у вас будет золота, тем больше его будет и в хранилище.",
    ["Bank Safe"] = "Банковский сейф",
    ["Gain access to the bank safe by acquiring 3,000 favor with your pledged faction. Once acquired, you can access your bank and guild bank via this safe."] = "Gain access to the bank safe by acquiring the <TBD item/collectible>. Once acquired, you can access your bank and guild bank via this safe.",
    ["Faction Banners"] = "Знамена фракций",
    ["Display your allegiance to your faction. After gaining 2,000 favor with your faction, unlock the ability to display their banners in your courtyard."] = "Продемонстрируйте свою преданность выбранной фракции! Заслужив расположение (окончательное значение еще не определено) своей фракции, вы получите возможность размещать ее знамена у себя во дворе.",
    ["The Worm Cult trapped four Undaunted heroes within soul-forged weapons across Solstice. Free the trapped heroes and learn the truth of their tale in a melancholy tome."] = "Культ Червя заключил четверых Неустрашимых в одушевленное оружие, что ныне разбросано по всему Солстису. Освободите плененных героев и узнайте их подлинную историю, прочтя печальную повесть.",
    ["The Secret Stone Guardians"] = "Хранители тайн Камня",
    ["The Amber Egg and Cerulean Sea"] = "Янтарное яйцо и лазурное море",
    ["You have life again. Use it and move forward. Without sadness. Without regret."] = "Тебе дарована новая жизнь. Не упусти же свой шанс, иди вперед. Без грусти. Без сожаления.",
    ["My tired knees are getting too old for all this bending."] = "Стара я становлюсь для такой работы. Колени болят…",
    ["This one is with you, friend! Your bravery invigorates Tibarr!"] = "Каджит пойдет с тобой, <<player{друг/подруга}>>! Твоя смелость воодушевляет Тибарра!",
    ["You can do it, hero! Don't let the Dragon's ferocity and tricks distract you!"] = "Ты справишься, <<player{герой/героиня}>>! Не давай ярости и хитрости Дракона тебя отвлечь!",
    ["Careful of the Dragon's breath, friend! Tibarr will meet you outside, after you give the coin to the Orc."] = "Берегись дыхания Дракона, <<player{друг/подруга}>>! Отдай монету орку, а потом приходи к Тибарру — он будет ждать снаружи.",
    ["Empty? Oh, Yesei's a cruel one! And I see he has some help."] = "Что, пусто? Ох, до чего же Йесею не везет! Но, вижу, он нашел себе <<player{помощника/помощницу}>>.",
    ["Persistent! But the tides flow in my favor!"] = "Какое упорство! Но в этих ручьях я как рыба в воде!",
    ["Pesky … mud! Very well. You hooked me. Let's talk."] = "Вот же дрянная… грязь! Ладно, признаю, ты меня <<player{поймал/поймала}>>. Давай поговорим.",
    ["Well done. Now, smear the mud on the effigy."] = "Отлично! А теперь размажь грязь по фигуре.",
    ["Tamriel's flora is blessed, friend. Let's talk."] = "Растения Тамриэля получили благословение, <<player{друг/подруга}>>. Давай поговорим.",
    ["I smell blood in the water. It's time to fight!"] = "Я чую в воде кровь. Пора сразиться!",
    ["You two! Take this map and get this boulder. Just remember to lift with your legs!"] = "Эй вы! Возьмите эту карту да притащите валун сюда. Только спины не сорвите!",
    ["It's no use, traveler. I gave it all I had and all I did was break my favorite hammer."] = "Бесполезно, <<player{путешественник/путешественница}>>. Я бил изо всех сил, но только любимый молот сломал.",
    ["That should brighten Garth's mood! Wait …."] = "Это наверняка поднимет Гарту настроение! Сейчас, погоди…",
    ["May Alik'r's desert winds steer you true, my friend. Farewell."] = "Да направят тебя ветра пустыни Алик’р, <<player{друг/подруга}>>. Прощай.",
    ["Rest well, Master Hassavir. Your winds still soar from Yokuda's depths, and now guide me."] = "Покойся с миром, наставник Хассавир. Твои ветра по-прежнему дуют из глубин Йокуды и ведут меня.",
    ["Come, friend. The ritual circle's ready. I wouldn't do this without you."] = "Поспеши, <<player{друг/подруга}>>. Ритуальный круг готов. Я не хотела начинать без тебя.",
    ["It is done."] = "Готово.",
    ["No! Just when Sharadak had her in his clutches, she slips away. Torment! Madness! This one may never recover! … Which way did she go?"] = "Нет! Шарадак уже почти ее схватил, а она опять ускользнула. О мучение! О безумие! Каджит никогда не оправится от этого удара!.. Так, куда она побежала?",
    ["Well, maybe I'll … I'll just scrap this song."] = "Что ж, пожалуй, я… просто откажусь от этой песни.",
    ["Vanus's dupe and Meridia's fool. Have you come to witness my triumph?"] = "Марионетка Вануса и шут Меридии. Пришли полюбоваться на мой триумф?",
    ["Come on, Jeetra—give me a little credit. I'm just looking. Something's off about this door, I'm trying to figure out what."] = "Не будь такой колючей, Джитра. Я просто хочу посмотреть. С этой дверью что-то не так, и я пытаюсь понять, что именно.",
    ["Destroy the soul flayer, mainlander! It blocks our path!"] = "Уничтожь пожиратель душ, <<player{гость/гостья}>> с большой земли! Он стоит у нас на пути!",
    ["When you have the Embellished Dance Card, Rosy Boutonniere, and Sanguine's Goodbye Kiss: \nUse to combine into the Roseblood Wings Recall customized action."] = "Собрав роскошную бальную карточку, розовую бутоньерку и прощальный поцелуй Сангвина, используйте их, чтобы объединить.\nВы получите настраиваемое действие — перемещение «Крылья крови и роз».",
    ["Today's New Life offering is complete. I should speak to Lanullin and ask about my reward."] = "Сегодняшний дар в честь Праздника Новой жизни вручен. Пора поговорить с Лануллин и напомнить ей о моей награде.",
    ["I delivered the New Life offering to Lanullin's elder. I should let her know I completed my task."] = "Я <<player{отнес/отнесла}>> дар Новой жизни старейшине общины Лануллин. Нужно сказать ей, что задание выполнено.",
    ["I need to prepare a banana surprise offering for Lanullin's elder. The grocers and taverns nearby should have a recipe and cooking fire if I need them."] = "Мне нужно приготовить банановый сюрприз в дар старейшине общины Лануллин. Рецепты и огонь для приготовления пищи, если они мне понадобятся, можно найти в ближайших бакалейных лавках и тавернах.",
    ["I need to prepare a carrot soup offering for Lanullin's elder. The grocers and taverns nearby should have a recipe and cooking fire if I need them."] = "Мне нужно приготовить морковный суп в дар старейшине общины Лануллин. Рецепты и огонь для приготовления пищи, если они мне понадобятся, можно найти в ближайших бакалейных лавках и тавернах.",
    ["I need to prepare a baked potato offering for Lanullin's elder. The grocers and taverns nearby should have a recipe and cooking fire if I need them."] = "Мне нужно приготовить печеный картофель в дар старейшине общины Лануллин. Рецепты и огонь для приготовления пищи, если они мне понадобятся, можно найти в ближайших бакалейных лавках и тавернах.",
    ["Time to deliver the offering. The list Lanullin gave me should say whom to offer this to and where."] = "Пора доставить дар. В записке, которую дала мне Лануллин, указано, кому и куда его отнести.",
    ["Tibarr wants me to steal a coin from the lair of Rawl'kha's Dragon. He mentioned the lair was in a cavern nearby."] = "Тибарр хочет, чтобы я <<player{украл/украла}>> монету из логова Дракона Рол’ки. По его словам, логово находится в пещере неподалеку.",
    ["I completed Tibarr's New Life festivity and gave the Dragon's coin to the Orc beggar. Now to claim my own reward from Tibarr."] = "Я <<player{принял/приняла}>> участие в празднестве Новой жизни Тибарра и <<player{отдал/отдала}>> монету Дракона нищему орку. Пора получить у Тибарра свою награду.",
    ["I swiped the Dragon's coin and donated it to the Orc beggar. Now I should report back to Tibarr."] = "Я <<player{украл/украла}>> монету Дракона и <<player{отдал/отдала}>> ее нищему орку. Нужно вернуться к Тибарру.",
    ["I swiped the Dragon's coin. Tibarr wants me to give it to the Orc beggar, Yarg. I should talk to him and give him the coin."] = "Я <<player{украл/украла}>> монету Дракона. Тибарр хочет, чтобы я <<player{отдал/отдала}>> ее нищему орку Яргу. Надо поговорить с ним и отдать монету.",
    ["Yesei last saw the Dakoi in the streams near Stormhold's outskirts. I should start fishing there."] = "В последний раз Йесей видел дакоя в ручьях близ Стормхолда. Там мне и следует начать рыбалку.",
    ["I returned to Yesei with fish from the Dakoi. I should speak to him and ask about my reward."] = "Я <<player{вернулся/вернулась}>> к Йесею с рыбой от дакоя. Надо поговорить с ним и напомнить о награде.",
    ["I caught the Dakoi, revealed to be an Argonian acting like a fish. He gave me one to hand to Yesei. I should return to him."] = "Я <<player{поймал/поймала}>> дакоя. Оказалось, что на самом деле это аргонианин, который играет роль рыбы. Он дал мне рыбу для Йесея. Нужно вернуться к нему.",
    ["Dailonda said she needs fresh mud to spring the Mudman to life. Time to dig."] = "По словам Дайлонды, чтобы вдохнуть в Грязевика жизнь, нужна свежая грязь. Придется копать.",
    ["I smeared the mud and helped Dailonda complete the Mudman effigy. I should speak to her and ask about my reward."] = "Я <<player{размазал/размазала}>> грязь и <<player{помог/помогла}>> Дайлонде закончить Грязевика. Надо поговорить с ней и напомнить о награде.",
    ["Mahagog said I could find an Orsimer hammer to use for the challenge at a blacksmith's station in the fortress. I should get it and try to smash the Oblivion boulder."] = "По словам Махагога, орсимерский молот для состязания можно взять в кузнице крепости. Надо сходить туда, взять молот и попробовать разбить валун из Обливиона.",
    ["I proved my strength and destroyed the Oblivion boulder. Time to speak to Mahagog about my reward."] = "Я <<player{разбил/разбила}>> валун из Обливиона и <<player{доказал/доказала}>> свою силу. Пора поговорить с Махагогом о моей награде.",
    ["I need to find some honeycomb to put Garth in a good mood for New Life. The hermit said the forests near Hunter's Glade should have some."] = "Чтобы поднять Гарту настроение к Празднику Новой жизни, мне нужно раздобыть медовых сот. Отшельник сказал, что их можно найти в лесах неподалеку от Охотничьей поляны.",
    ["I fed Garth the honeycomb and saved all of Tamriel, according to the hermit. I should speak to him and ask about my reward."] = "Я <<player{угостил/угостила}>> Гарта сотами и, если верить отшельнику, <<player{спас/спасла}>> этим весь Тамриэль. Пора спросить у него о награде.",
    ["I need to fill the waterskin with Yokuda's waters in the west. Once done, I can perform the ritual of Anseilak at Motalion Necropolis."] = "Мне нужно наполнить мех водами Йокуды на западе. После этого я смогу совершить ансейлак в некрополе Моталион.",
    ["I helped Hassavir complete his pilgrimage and performed Anseilak for the fallen Yokudan mages. I should speak to him and ask about my reward."] = "Я <<player{помог/помогла}>> Хассавиру завершить паломничество и <<player{совершил/совершила}>> ансейлак для павших йокуданских магов. Нужно поговорить с ним и спросить о моей награде.",
    ["Lanullin is preparing her offerings to the elders in Auridon. I should speak to her and learn what I can do to help."] = "Лануллин готовит угощение в дар старейшинам Ауридона. Надо спросить, чем я могу ей помочь.",
    ["I should travel to Rawl'kha and find Tibarr to learn more about his New Life festivity."] = "Мне нужно отправиться в Рол’ку, найти Тибарра и узнать подробности о его праздновании Новой жизни.",
    ["I should look for Yesei in Stormhold and see if he needs help catching the Dakoi fish."] = "Надо разыскать Йесея в Стормхолде и спросить, не нужна ли ему помощь в ловле дакоя.",
    ["I should speak to Dailonda in Elden Root to find out more about what she needs help with."] = "Мне нужно поговорить с Дайлондой в Элден-Руте и узнать, какая помощь ей требуется.",
    ["Mahagog is hosting the festivity with a group of Orcs at Stonetooth Fortress. I should speak to him to learn more about this contest of strength."] = "Махагог устраивает празднество в крепости Каменного Зуба вместе с другими орками. Надо поговорить с ним и спросить об этом состязании в силе.",
    ["The traveler was said to be seen out in Sentinel asking for help. I should start there and speak to them."] = "Говорят, просившего о помощи путника видели в Сентинеле. Нужно отправиться туда и поговорить с ним.",
    ["Anicus mentioned the hermit was spotted in the Rift. I should speak to him and learn more about his pet bear's needs."] = "По словам Аника, отшельника видели в Рифте. Надо отправиться туда, поговорить с ним и узнать, чего не хватает его медведю.",
    ["I helped Jahesi perform Anseilak and gave peace to the fallen Yokudan mages. I should speak to her about my reward."] = "Я <<player{помог/помогла}>> Джахеси совершить ансейлак и помочь павшим йокуданским магам обрести покой. Нужно поговорить с ней о моей награде.",
    ["I need bait to catch the Dakoi fish. Yesei mentioned the Shadowscale camp west from Stormhold might have a bottle of bloodwine that could work."] = "Чтобы поймать дакоя, нужна наживка. По словам Йесея, в лагере Темных ящеров к западу от Стормхолда должно быть кровавое вино, которое может нам помочь.",
    ["Mahagog mentioned he fought a group of Daedra west of Stonetooth Fortress that left behind an Oblivion boulder for us to smash. I should search the area, find the boulder, and mark its location on my map."] = "Махагог рассказал мне, что недавно сражался с даэдра и они оставили валун из Обливиона, который как раз подойдет для состязания. Битва происходила к западу от крепости Каменного Зуба. Мне нужно осмотреть эти места, найти валун и отметить его на карте.",
    ["I found the strange Oblivion boulder. I should return to Mahagog and let him know exactly where it is."] = "Я <<player{нашел/нашла}>> странный валун из Обливиона. Надо вернуться к Махагогу и сообщить, где он находится.",
    ["Mahagog is waiting for me. I should tell him about the boulder I found for our challenge."] = "Махагог ждет меня. Надо рассказать ему о валуне для нашего состязания, который мне удалось найти.",
    ["Sirilonwe noticed an abandoned camp to the southeast. She guesses that it might belong to Terinvel and Ormard. I should search it for evidence of where they went."] = "Сирилонве заметила брошенный лагерь на юго-востоке. Она предполагает, что он может принадлежать Теринвелу и Ормарду. Надо осмотреть лагерь и попытаться выяснить, куда они отправились.",
    ["I offered Sirilonwe advice about how to handle Terinvel's transformation into a vampire. It remains to be seen if she takes it. I should talk to her about my reward."] = "Я <<player{дал/дала}>> Сирилонве совет, как поступить с превращением Теринвела в вампира. Правда, еще не известно, последует ли она ему. Надо поговорить с ней о моем вознаграждении.",
    ["The abandoned campsite outside Ashbound Hall definitely belonged to Terinvel and Ormard. I found notes from them claiming to know of a side entrance into the Hall. I should talk to Sirilonwe about this."] = "Брошенный лагерь возле Пепельного зала и впрямь принадлежал Теринвелу и Ормарду. Судя по найденным мною заметкам, им стало известно о потайном входе в Зал. Надо обсудить это с Сирилонве.",
    ["Terinvel's dropped note describes a cave entrance that leads inside Ashbound Hall. I should explore to the southwest to find it."] = "В записке, которую обронил Теринвел, упоминается пещера к юго-западу отсюда, через которую можно попасть в Пепельный зал. Надо попытаться найти ее.",
    ["I found a crack in the stone that could lead into some caves. This might be the side entrance into Ashbound Hall that Terinvel mentioned in his notes. I should head in and see where it leads me."] = "Я <<player{нашел/нашла}>> трещину в камне, которая, похоже, ведет в пещеру. Возможно, это и есть потайной вход в Пепельный зал, о котором упоминал Теринвел. Надо проверить, куда он меня приведет.",
    ["A Stirk Fellowship scout named Mihnassi told me about the missing Terinvel and Sirilonwe's need for aid. She said I could find the academic on the road north of Ashbound Hall. I should track her down."] = "Разведчица Братства Стирка по имени Минасси рассказала мне о пропавшем Теринвеле и о том, что ученая по имени Сирилонве нуждается в помощи. По ее словам, Сирилонве сейчас где-то на дороге к северу от Пепельного зала. Надо разыскать ее.",
    ["The crack in the wall led into a cave. I see an opening to a building that may be Ashbound Hall. I should talk to Sirilonwe to discuss our next move."] = "Трещина в стене и впрямь привела меня в пещеру. Я вижу вход в какое-то строение — вероятно, это и есть Пепельный зал. Надо обсудить дальнейшие действия с Сирилонве.",
    ["Sirilonwe confirmed that the cave opens into Ashbound Hall. She urged caution as we explore the prison. Vampires lurk everywhere. I should start my search for Terinvel."] = "Сирилонве подтвердила, что пещера ведет в Пепельный зал. По ее словам, внутри нужно будет соблюдать величайшую осторожность — вампиры там на каждом шагу. Пора отправляться на поиски Теринвела.",
    ["My search revealed a medallion etched with strange characters. I also found a note describing a method to unlock the sealed door. I need to show these to Sirilonwe."] = "В ходе поисков я <<player{обнаружил/обнаружила}>> медальон, на котором были выгравированы странные символы. Еще я <<player{нашел/нашла}>> записку, в которой описывается способ открыть запечатанную дверь. Надо показать мои находки Сирилонве.",
    ["Sirilonwe identified the medallion I found as the Aspect of Brutality. It's part of a system that unlocks doors around Ashbound Hall. The note I found describes the Aspect's correct arrangement. I should place this on the unlocking"] = "Сирилонве опознала в найденном мной медальоне Аспект жестокости — часть механизма, открывающего двери в Пепельном зале. В найденной мной записке описано правильное расположение таких Аспектов. Надо проверить, сработает ли оно.",
    ["A young vampire revealed herself to us and claimed she meant no harm. It seems she's the source of the mysterious whispering we heard. I should find out why she's following us."] = "Перед нами предстала молодая вампирша, которая заявила, что не желает нам зла. Похоже, это ее таинственный шепот мы слышали. Надо выяснить, почему она нас преследует.",
    ["Azartha gave us some helpful information for dealing with Ashbound Hall. Rooms that are more brightly lit than others will keep us safe. Apparently we can find a map in one of those rooms. I should resume my search of the prison."] = "Азата поделилась с нами ценными сведениями о Пепельном зале. Помещения, что освещены ярче всего, будут для нас безопасны. По ее словам, в одной из таких комнат мы найдем карту. Надо продолжить осмотр этой тюрьмы.",
    ["We found another room bathed in purple light. Azatha mentioned we might find a map for Ashbound Hall in a room like this. I should search for one."] = "Мы нашли еще одно помещение, озаренное фиолетовым светом. Азата упоминала, что в одном из них может оказаться карта Пепельного зала. Надо поискать ее.",
    ["Our exploration of Ashbound Hall brought us to a magically sealed door. We found a safe room nearby that could provide clues to opening the door. I should look around for anything that stands out."] = "Исследуя Пепельный зал, мы отыскали дверь, запечатанную при помощи магии. Неподалеку обнаружилась безопасная комната. Может, в ней найдутся подсказки, как открыть дверь? Надо осмотреться, обращая особое внимание на все, что выглядит необычно.",
    ["During my search for a map of Ashbound Hall, I also found another Aspect medallion. Maybe Sirilonwe can tell me which one it is. I should show it to her along with the map."] = "В ходе поисков карты Пепельного зала я <<player{нашел/нашла}>> еще один медальон-Аспект. Может, Сирилонве подскажет, какой именно. Надо показать его ей вместе с картой.",
    ["As Sirilonwe and I crossed a bridge, we heard whispering from the shadows. The whispers seem to be talking about us. I should hunt down the source to see if its dangerous."] = "Переходя мост, мы с Сирилонве услышали из темноты шепот. Кажется, речь шла о нас. Надо найти источник шепота, чтобы понять, не представляет ли он опасности.",
    ["With the help of Sirilonwe's spell, I was able to clear the rubble from the bridge. Now I can continue my search of Ashbound Hall for Terinvel."] = "С помощью чар Сирилонве мне удалось убрать обломки с моста. Теперь я могу продолжить поиски Теринвела в Пепельном зале.",
    ["We entered a new section of Ashbound Hall and found another vampire calling out for help. Like Azatha, he claims to be harmless and didn't attack on sight. I should talk to him to see if he can provide information for finding Terinvel."] = "Войдя в новую часть Пепельного зала, мы обнаружили еще одного вампира, который звал на помощь. Как и Азата, он утверждает, что не представляет угрозы, и, заметив нас, не стал нападать. Надо поговорить с ним — возможно, он поможет нам в поисках Теринвела.",
    ["Despite Sirilonwe healing Liviano, he decided to attack us. She turned him into ashes. I should search his remains to see if he did have the Aspect he claimed to."] = "Сирилонве вылечила Ливанио, но он все-таки напал на нас. Сирилонве обратила его в прах. Надо обыскать останки — ведь Ливанио утверждал, что нашел один из Аспектов.",
    ["Fortunately, I found an Aspect among Livanio's ashes. Lucky for us, Sirilonwe's fire spell didn't melt it. I should check on her to make sure she's all right after this attack."] = "К счастью, мне удалось найти Аспект среди праха Ливанио. Нам повезло, что огненное заклинание Сирилонве его не расплавило. Надо узнать, как она чувствует себя после нападения.",
    ["We unlocked the door by using the Aspects, and entered the next section of Ashbound Hall. Now we can continue our search of this prison for Terinvel."] = "Мы открыли дверь с помощью Аспектов и вошли в следующую часть Пепельного зала. Теперь мы можем продолжить поиски Теринвела в этой тюрьме.",
    ["Sirilonwe feels justified in killing Livanio in self-defense. Plus, now we have another important Aspect to help us through this prison. I should follow her into the next section."] = "Сирилонве считает убийство Ливанио оправданным — она просто защищалась. Кроме того, теперь у нас есть еще один важный Аспект, который поможет пройти через эту тюрьму. Надо последовать за Сирилонве дальше.",
    ["The injured Ormard implied that he hid an Aspect somewhere in the central courtyard. I need to look through all this damage until I find it."] = "Раненый Ормард намекнул, что спрятал Аспект где-то в центральном дворе. Надо отыскать его среди обломков.",
    ["I managed to find an Aspect among the rubble of the central courtyard. Ormard didn't do that good of a job hiding it. I should show it to Sirilonwe."] = "Мне удалось найти Аспект среди обломков в центральном дворе. Ормард не слишком хорошо его спрятал. Нужно показать Аспект Сирилонве.",
    ["The only way out of the central courtyard is through another magically sealed door. I need to place the Aspects in the proper order to unlock the magic."] = "Из центрального двора можно выбраться только через еще одну дверь, запечатанную магией. Чтобы развеять чары, мне нужно расположить Аспекты в правильном порядке.",
    ["We finally caught up with Terinvel. Unfortunately, a powerful vampire named the Elder has captured and bound him. I only see one way to get him free. I should kill the Elder."] = "Мы наконец нашли Теринвела. К несчастью, его пленила и связала могущественная старейшая вампирша. Я вижу только один способ освободить его. Надо убить старейшую.",
    ["Terinvel is free, even if he doesn't immediately appreciate it. Sirilonwe conjured a portal so that we can leave Ashbound Hall. I should join her outside."] = "Теринвел свободен, однако особой благодарности пока не выказал. Сирилонве открыла портал, чтобы мы могли покинуть Пепельный зал. Нужно встретиться с ней снаружи.",
    ["I stepped through the portal and arrived outside Ashbound Hall. I can hear Terinvel and Sirilonwe argue with each other. I should check on the newly rescued researcher and see how he feels."] = "Я <<player{прошел/прошла}>> через портал и <<player{оказался/оказалась}>> за пределами Пепельного зала. Я слышу, как спорят Теринвел и Сирилонве. Надо узнать, как там наш спасенный исследователь.",
    ["Despite all our efforts, Terinvel didn't escape unscathed. He admits that the Elder passed on vampirism to him. He seems quite excited about the power growing inside him. I should talk to Sirilonwe about this."] = "Несмотря на все наши усилия, Теринвелу не удалось остаться невредимым. Он признался, что старейшая заразила его вампиризмом. Похоже, он очень заинтересован растущей в нем силой. Надо обсудить это с Сирилонве.",
    ["After Sirilonwe cast her spell, ghostly versions of Terinvel and Ormard appeared. This was a recreation of a moment in the past. They discussed their plans to go deeper into the Ashbound Halls. I should talk to Sirilonwe about this."] = "Когда Сирилонве сотворила чары, перед нами появились призраки Теринвела и Ормарда, и мы увидели фрагмент прошлого. Они обсуждали свой план углубиться в Пепельный зал. Надо поговорить об этом с Сирилонве.",
    ["With our combined strength, Sirilonwe and I managed to defeat the Elder. Terinvel is now free, if a bit ungrateful. I should wait until he's on his feet to see what we do next."] = "Объединив силы, мы с Сирилонве сумели победить старейшую. Теперь Теринвел свободен, хотя и не слишком нам за это признателен. Надо дождаться, когда он придет в себя, — тогда и решим, что делать дальше.",
    ["When I placed the Aspect of Brutality into the mechanism, the ward disappeared from the door. Sirilonwe and I should continue our search of Ashbound Hall for Terinvel."] = "Стоило мне поместить Аспект жестокости в механизм, как барьер на двери тут же исчез. Нам с Сирилонве надо продолжить поиски Теринвела в Пепельном зале.",
    ["Now that we have a rough map of Ashbound Hall, finding Terinvel should be slightly easier. Time to continue forward with our search."] = "Теперь у нас есть набросок карты Пепельного зала, который наверняка облегчит поиски Теринвела. Пора двигаться вперед.",
    ["Sirilonwe has a spell that can clear the rubble that blocks our path. Once she starts casting, I need to smash the rubble."] = "Сирилонве знает чары, которые могут убрать обломки, преграждающие нам путь. Как только она начнет творить их, мне нужно будет ударить по обломкам.",
    ["Sirilonwe and I finally reached the central courtyard and it's in shambles. However, we did manage to find an injured Ormard laying on the ground. He claims to have expected us. I should press him to tell me where Terinvel went."] = "Мы с Сирилонве наконец-то добрались до центрального двора, от которого мало что осталось. Впрочем, на земле мы увидели раненого Ормарда. Он утверждает, что ждал нас. Надо выпытать у него, куда делся Теринвел.",
    ["Sirilowe spotted a camp fire tucked away in a heavily damaged area of the Hall. She thinks it's worth searching. I should look through the camp for any clues."] = "Сирилонве заметила костер, укрытый в сильно разрушенной части зала. Она считает, что там стоит осмотреться. Надо попытаться найти какие-нибудь зацепки.",
    ["Ashbound Hall's crash landing into Solstice created rubble everywhere. Some of it blocks a bridge we need to cross. I should talk to Sirilonwe about how to clear it."] = "После приземления Пепельного зала на Солстисе все кругом завалено обломками. Часть из них преграждает нам путь через мост. Нужно обсудить с Сирилонве, как от них избавиться.",
    ["I found a hat that Sirilonwe claims belong to Ormard. Apparently it spurred an idea in her. I should watch what comes from her spell."] = "Я <<player{нашел/нашла}>> шляпу, которая, по словам Сирилонве, принадлежит Ормарду. Кажется, это натолкнуло ее на какую-то мысль. Надо посмотреть, что получится из ее чар.",
    ["In the memory that Sirilonwe recreated, Ormard wanted to get to a crater that's just ahead. Now we have a direction for a search. I should find this crater."] = "В воспроизведенном Сирилонве кусочке недавнего прошлого Ормард хотел добраться до кратера, который находится совсем рядом. Теперь мы знаем, в каком направлении вести поиски. Нужно найти этот кратер.",
    ["We reached the area of Ashbound Hall that Ormard referred to as a crater. It certainly matches the title. Should continue my search for Terinvel by crossing it."] = "Мы добрались до той части Пепельного зала, которую Ормард назвал кратером. Это название действительно ей подходит. Нужно пересечь кратер и продолжить поиски Теринвела.",
    ["We crossed through the crater, but saw no sign of Terinvel or Ormard. Sirilonwe suggested we keep heading in this direction. Perhaps we're hot on their heels. I should continue my search of Ashbound Hall."] = "Мы пересекли кратер, но не увидели никаких следов Теринвела и Ормарда. Сирилонве предложила идти дальше в этом же направлении. Возможно, они уже недалеко. Нужно продолжить осмотр Пепельного зала.",
    ["Sirilonwe and I came across another door sealed with magic. Looks like I need to use the Aspects we collected to unlock it. I should find the right placement for the medallions to unlock the door."] = "Мы с Сирилонве наткнулись на еще одну дверь, запечатанную магией. Похоже, чтобы открыть ее, нужно использовать собранные Аспекты. Но сначала надо понять, в каком порядке они должны располагаться.",
    ["I placed all the Aspects in their proper spot and unlocked the door. According to Ormard, Terinvel should be just beyond, but he'll be in the company of someone called the Elder. I should go confront her so we can get out of here."] = "Я <<player{поместил/поместила}>> все Аспекты на нужные места и <<player{открыл/открыла}>> дверь. По словам Ормарда, Теринвел должен быть прямо за ней, но не один, а в компании некой старейшей. Мне придется разобраться с ней, чтобы мы могли выбраться отсюда.",
    ["For Lanullin, celebrating New Life involves giving back to the esteemed elders of her community through good meals. I agreed to help her prepare and deliver them."] = "Для Лануллин празднование Новой жизни — это возможность отблагодарить почтенных старейшин ее общины, приготовив для них хорошую трапезу. Я <<player{согласился/согласилась}>> помочь ей с готовкой и доставкой угощений.",
    ["Food for New Life"] = "Угощение в честь Новой жизни",
    ["I met a Khajiit in Rawl'kha who asked me to try and steal coin from a Dragon for his New Life festivity, and then give it to a needy Orc nearby. Apparently, its tricks are challenging to some. I agreed to participate."] = "В Рол’ке мне встретился каджит, который предложил мне попытаться украсть монету у Дракона в честь Праздника Новой жизни, а затем отдать ее нищему орку неподалеку. Очевидно, это не всем дается легко. Я <<player{согласился/согласилась}>> попробовать.",
    ["The Dragon's Hoard"] = "Сокровища Дракона",
    ["I met an Argonian angler in Stormhold frustrated over not being able to catch the Dakoi, a special fish that's said to appear every New Life festival and bring good fortune. I agreed to hunt and catch the Dakoi for him."] = "В Стормхолде мне встретился расстроенный рыбак-аргонианин, которому никак не удается поймать дакоя — особую рыбу, которая, как говорят, появляется во время каждого Праздника Новой жизни и приносит удачу. Я <<player{согласился/согласилась}>> попытаться поймать дакоя вместо него.",
    ["The Hunt for Dakoi"] = "Охота на дакоя",
    ["I met a Wood Elf in Grahtwood trying to construct a Mudman effigy for the New Life festival to bless all of Tamriel's green. I agreed to help her gather mud and complete the effigy since her kin aren't there to help."] = "В Гратвуде я <<player{встретил/встретила}>> лесную эльфийку, которая лепит фигуру Грязевика на Праздник Новой жизни, чтобы благословить Зеленый Лес Тамриэля. Я <<player{согласился/согласилась}>> помочь ей закончить Грязевика, поскольку ее родных нет рядом.",
    ["The Mudman"] = "Грязевик",
    ["I met a group of Orcs in Stonetooth Fortress breaking boulders for Betnikh's Boon during the New Life Festival. Their leader proposed I search an area where he fought Daedra for a stronger boulder to break. I accepted his challenge."] = "Во время Праздника Новой жизни в крепости Каменного Зуба мне повстречались орки, которые разбивали валуны ради Благословения Бетника. Их предводитель предложил мне разыскать на месте его сражения с даэдра большой валун и разбить его. Я <<player{принял/приняла}>> вызов.",
    ["Betnihk's Boon"] = "Благословение Бетника",
    ["A member of the Skaal tribe believes the mood of his bear, Garth, during New Life, will determine the fate of Tamriel. He believes honeycomb might make him happy. I agreed to help him."] = "Мне повстречался скаал, твердо уверенный, что судьба всего Тамриэля зависит от того, в хорошем ли настроении пребывает во время Праздника Новой жизни его медведь Гарт. По его мнению, медведя могут порадовать медовые соты. Я <<player{согласился/согласилась}>> помочь.",
    ["The Judgment of Garth"] = "Суд Гарта",
    ["I met a wandering traveler out in Sentinel on pilgrimage to give fallen Yokudan mages Anseilak, a ritual that brings them peace. However, since he's unable to complete the journey, I agreed to help him."] = "В Сентинеле мне повстречался паломник, желающий совершить ансейлак — ритуал, призванный помочь павшим йокуданским магам обрести покой. Поскольку сам он не может пройти этот путь, я <<player{согласился/согласилась}>> ему помочь.",
    ["The Desert and the Sea"] = "Пустыня и море",
    ["Two academics, Sirilonwe and Terinvel, came to study Ashbound Hall, a vampire prison that arrived with the planemeld on Solstice. However, Terinvel went missing and Sirilonwe needs help finding him among the deadly vampires."] = "Двое ученых, Сирилонве и Теринвел, собирались исследовать Пепельный зал — тюрьму для вампиров, которая появилась на Солстисе в ходе Слияния миров. Однако Теринвел пропал, и Сирилонве нужна помощь, чтобы отыскать его среди опасных вампиров.",
    ["Antique Map of Solstice"] = "Старинная карта Солстиса",
    ["A simple stone for a complex task. To connect a family through the ages. Stone is chipped to have many small indentations. Stone-Nest tradition says each face retains some flavor, some memory, of meals past."] = "На этот простой камень возложена непростая задача — поддерживать связь между поколениями одной семьи на протяжении многих лет. На его поверхности сделано множество мелких углублений. Согласно поверью каменных-гнезд, каждое из них сохраняет определенный вкус, память о прошлых трапезах.",
    ["Five is a number that comes up a lot with Hircine. These fangs represent the Spear of Bitter Mercy, also called Spear with Five Points. They would have been fixed in a warmask belonging to a great chief of the Ket Keptu."] = "Число «пять» часто связывают с Хирсином. Эти клыки символизируют Копье Горькой Милости, также называемое Копьем о Пяти Концах. Вероятно, эти клыки были частью боевой маски, принадлежавшей какому-нибудь великому вождю кет-кепту.",
    ["Ah, of course! The Ket Keptu were hunters and warrior-smiths, a people devoted to the Lord of the Hunt. To carry the Spear of Bitter Mercy was a high honor for their great champions. Whoever wore this warmask was indeed favored by Hircine!"] = "Ну конечно же! Кет-кепту были охотниками и воинами-кузнецами и почитали Владыку Охоты. Носить Копье Горькой Милости было большой честью для их великих героев. Хозяин этой боевой маски поистине был любимцем Хирсина!",
    ["I practice conjuration magic."] = "Я владею магией призыва.",
    ["Day 1\n\nNo wonder we're the only fools willing to walk into this deathtrap. This side of Solstice is nothing but destruction. Thankfully, some soldiers from this Stirk Fellowship helped us avoid some Daedra and a Worm Cult patrol.\n\n Sadryn promises a fortune so big I'll never have to open my toolbox again. And he really means it. After we finish this job and I hand over my trap designs, they're his for good.\n\nHonestly, it feels like giving up part of my identity, but mother needs the gold. I hate seeing her like this. She barely even recognizes me anymore. Her ailment is worsening.\n\n* * *\nDay 2\n\nWe finally made camp in some relatively calm part of Eastern Solstice, and yet my mind still battles over whether I can actually fulfill my end of this bargain. No, I'm sure now.\n\nI'll set the traps tomorrow, but I've decided I can't part with my plans for how to build them. Father helped me design these. Building every trap makes it feel like he's still with me, and mother wouldn't want me to sell my knowledge like this, either.\n\nI'll tell Sadryn and still help him complete this hunt. I need the gold. But after that we'll need to settle on a new deal.\n\n* * *\nSadryn became so angry when I told him, he went completely mad! Oh gods, he stabbed me! I managed to slash his chest, drive him off. I should have aimed for his heart.\n\nIt hurts so much. The blood won't stop flowing. I'm hiding, but I hear him looking for me. It's getting harder to write.\n\nMother, I'm sor—"] = "День 1\n\nМеня даже не удивляет, что только нам хватило ума по доброй воле отправиться в эту западню. В этой части Солстиса царят разруха и гибель. К счастью, несколько солдат из Братства Стирка помогли нам не столкнуться с даэдра и дозорными культа Червя.\n\n Садрин обещал мне целое состояние, уверял, что мне никогда больше не придется браться за инструменты. И это не пустые слова. Когда мы закончим эту работу и я передам ему свои ловушки, они останутся у него навсегда.\n\nУ меня такое чувство, словно я отдаю частицу себя самой… но маме нужно золото. Мне невыносимо видеть ее такой. Она уже с трудом узнает меня. И ей все хуже.\n\n* * *\nДень 2\n\nМы наконец-то разбили лагерь в относительно спокойном уголке восточного Солстиса, однако меня до сих пор терзают сомнения, смогу ли я выполнить свою часть сделки. Впрочем, нет, я уже все решила.\n\nЗавтра я поставлю ловушки, но со своими чертежами расстаться не смогу. Мне помогал с ними отец. Когда я работаю над ловушками, у меня возникает ощущение, что он по-прежнему рядом со мной, да и мама вряд ли согласилась бы, чтобы я вот так просто взяла и продала свои знания.\n\nЯ поговорю с Садрином и в любом случае помогу ему довести эту охоту до конца. Мне нужно золото. Но потом нам нужно будет договориться о новой сделке.\n\n* * *\nКогда я сказала Садрину о своем решении, он рассвирепел. Просто обезумел! О боги, он даже ударил меня ножом! Мне удалось отогнать его, полоснув по груди. Надо было целиться в сердце…\n\nКак же больно. Кровь все не унимается. Я прячусь, но слышу, как он ищет меня. Писать все труднее.\n\nМама, прости м",
    ["Monthly report from Dark Adept Bruhlz.\n\nRecent Acquisitions:\n\n57 Stone-Nest Argonians taken from villages\n6 Escaped Stone-Nest Argonians, recaptured\n7 Stirk Fellowship soldiers \n1 Argonian necromancer, imprisoned for betraying the order\n\n<scribbled in a different hand>\nThe shackles need more souls to fully merge Coldharbour into this plane. And the improved devices must be tested. For that, we require more prisoners. If you cannot secure them, I will select volunteers from among the faithful in your nest.\n\nAnd make sure the traitor suffers. Sacrifice her last. Let her see what the flayers do to those she felt obligated to protect.\n\nMannimarco, King of Worms"] = "Ежемесячный отчет от темного адепта Брулза.\n\nПоследние поступления:\n\n57 аргониан из племени каменных-гнезд, уведенных из деревень;\n6 аргониан из племени каменных-гнезд, ранее совершивших побег;\n7 солдат Братства Стирка; \n1 аргонианка-некромантка — схвачена за предательство ордена\n\n<далее надпись другим почерком>\nЧтобы полностью втянуть Хладную Гавань в это измерение, Узам требуется больше душ. И еще необходимо испытать улучшенные устройства. Для этого нужны пленники. Если не сможешь их добыть, я выберу добровольцев из числа верных слуг в твоем логове.\n\nИ проследи, чтобы предательница как следует помучилась. Принеси ее в жертву последней. Пусть посмотрит, что пожиратели сделают с теми, кого она вдруг решила защищать.\n\nМаннимарко, Король Червей",
    ["Hail Mannimarco!\n\nYour humble servant reports that our experiments with the new soul flayers have been a resounding success. We disguised ourselves as merchants and brought one of the single-use flayers into a village near the Xul-Haj necropolis. The foolish lizards did not suspect a thing! We retreated to a safe distance to observe and activated the flayer. It performed as expected, sending out a burst of necrotic energy that killed everyone within the prescribed perimeter, sending their souls to the wraithforge. I will now return to collect the flayer for reconditioning.\n\nMay your work on the great rising swell our ranks with unstoppable undead warriors! May we gain an army of the dead from the depths of Xul-Haj!\n\nYour Servant,\nOverseer Bazgrum"] = "Приветствую, о Маннимарко!\n\nВаш покорный слуга сообщает, что наши эксперименты с новыми пожирателями душ увенчались грандиозным успехом. Переодевшись торговцами, мы привезли один из одноразовых пожирателей в деревню недалеко от некрополя Зул-Хадж. Глупые ящерицы и глазом не моргнули! Мы отошли на безопасное для наблюдений расстояние и привели пожиратель в действие. Он сработал в точности так, как и должен был: импульс некротической энергии убил всех, кто находился на определенном расстоянии, и пожиратель отправил их души в Призрачную кузницу. Сейчас я возвращаюсь туда, чтобы забрать пожиратель и перезарядить его.\n\nДа увенчается ваш великий труд успехом! Да поступит в наше распоряжение непобедимая армия нежити из глубин Зул-Хаджа!\n\nВаш слуга,\nбригадир Базгрум",
    ["Investigate the Village of Oozt-Tzel"] = "Осмотреть деревню Уцт-Тзел",
    ["You mentioned the Void. I take it you're here on personal business and want to keep it that way?"] = "Ты говорил о Пустоте. Я правильно понимаю, что ты здесь по своей личной инициативе?",
    ["No. I'm sorry. I was reassigned to Gristmung Hold when they needed more help with the soul flayer experiments. I do not know where they sent Vanus after that.\n\nBut he wrote a note and slipped it to me. Asked me to get it to Gabrielle when I could."] = "Нет. Прости. Меня перевели в крепость Гристмунг, когда культу понадобилась помощь в экспериментах с пожирателями душ. Куда после этого отправили Вануса, я не знаю.\n\nНо он написал записку и тайком передал мне. Попросил отдать Габриэль, когда будет возможность.",
    ["Big, wretched siege weapon. Hits with the very hatred of Coldharbour. Blows against a ship are ruinous, and those against crew are fatal.\n\nNo idea what it would do to Velehk Sain and his lot. But Suraj would love to find out."] = "Страшное, ужасное осадное орудие. Заряжено самой ненавистью Хладной Гавани. Попадет в корабль — разнесет в щепки! Попадет в команду — сразит наповал.\n\nА вот как оно подействует на Велека Сейна и его команду — неизвестно. Но Сурадж очень хотел бы это узнать!",
    ["Sithis worship has been a part of Argonian culture forever, though the Dread Father no longer features prominently in their day-to-day worship. \n\nBut here on Solstice, one warrior in each tribe, the death-dancer, still hews to the old ways."] = "Почитание Ситиса всегда было частью аргонианской культуры, хотя Отец Ужаса больше не занимает видного места в их повседневной религии.\n\nНо здесь, на Солстисе, в каждом племени есть один воин, который по-прежнему придерживается старых обычаев. Это и есть танцующий со смертью.",
    ["Kauldin studied under her. He was one of the apprentices she took under her wing and trained to be a marine.\n\nBut we saw her working with the cultists. She even struck down most of her apprentices. Kauldin's lucky to have survived."] = "Колдин был ее учеником. Одним из тех, кого она взяла под крыло и готовила к морской службе.\n\nНо мы заметили, что Фенворин помогает культистам. Она не пощадила почти никого из своих учеников. Колдину повезло: он выжил.",
    ["That tracks. We saw her carrying a staff and heading toward the gathering hall at the center of the lodge. When the cultist with her hurled a bolt of fire, I didn't think. I just leaped in front of Consewen.\n\nShe … she would do the same for me."] = "Все сходится. Мы видели, как она с посохом в руке шла в общий зал в центре штаба. Когда культист, который был с ней, метнул огненную стрелу, я не раздумывая бросилась ей наперерез. Я загородила Консевен собой.\n\nОна… она бы сделала для меня то же самое.",
    ["Master Tanertor is alive! That's good to hear!\n\nPlease, activate the portal gate so I can get Latanwen to a healer in Sunport."] = "Наставник Танертор жив?! Как я рада это слышать!\n\nПожалуйста, открой портал, чтобы я могла поскорее доставить Латанвен в Санпорт, к целителю!",
    ["I do not like to answer such broad questions with a simple yes or no. First off, I am not Meridia. Her powers are not mine to bestow. But power can be transferred from one receptacle to another.\n\nThe Light of Meridia should be no different."] = "Я не могу ответить на столь неоднозначный вопрос простым «да» или «нет». Я ведь все-таки не Меридия и не могу раздавать ее силы направо и налево. Но силу можно переместить из одного вместилища в другое.\n\nДумаю, Светоч Меридии не исключение.",
    ["I thought I heard shrieking. Didn't want to get my hopes up that it might have been her.\n\nPerhaps it's time I let those old bones go. If you're ready to move on, there's another favor I need to ask of you."] = "То-то мне показалось, что я слышала вопль. Не хотела тешить себя надеждой, что это кричит Зинарк.\n\nЧто ж, видимо, с костями пора попрощаться. Если ты <<player{готов/готова}>> к следующему шагу, то у меня есть для тебя поручение.",
    ["There are two sides to every story. Long after our ancestors first sealed Mor Naril, they had to fight off Corelanya forays. Elven records of those troubled times reside in the library of the Sea and Sword Lodge.\n\nYou could seek your answers there."] = "У любой истории есть и вторая сторона. Много лет спустя после того, как наши предки запечатали Мор-Нарил, им пришлось отражать набеги клана Кореланья. Свидетельства эльфов о тех смутных временах хранятся в библиотеке штаба Коллегии моря и меча.\n\nТы можешь поискать ответы там.",
    ["Hmm … very well. Allowing outsiders to have a look at the restricted parts of our collection is rather against the rules, but under these circumstances? I think it would be warranted.\n\nOne moment. I need to refer to our catalog."] = "Хм-м… Ну хорошо. Вообще-то мы не пускаем в закрытую секцию нашей библиотеки чужаков, но в сложившихся обстоятельствах, думаю, можно сделать исключение.\n\nПодожди минутку, я сверюсь с каталогом.",
    ["<These crumbling notes are covered in fading Jel glyphs. In the margins, written in Tamrielic, are translation notes left by a Stone-Shaper some centuries ago.>\n\n<Translation> \"The war is won and yet I continue to toil away. Perhaps the others were right. If one wishes to know the color of obsession, you need only look to my scales. At my aching, calloused claws shaped to the handles of my tools. But I do not work without purpose.\n\n\"I see a new hunger growing in the eyes of our leaders. They see my guardians not as protectors, but as weapons. Tools for a war beyond our shores. This is not why I built them. I will now spend my final years locking them away, along with their control stone. The wonders of this temple, once a testament to our courage, are now a trap for those seeking war in times of peace.\"\n\n* * *\n<Translator's Note> So the vault I glimpsed at the temple's center holds not viridian life, but the forms which were shaped from it. The voskrona. It is strange, translating the words of an Argonian as ancient as I feel. How I empathize with his aches as I see a slow, growing harshness to his glyphs. An unevenness that reveals a petrified shoulder. A locked wrist. Ailments that I too massage between quill strokes.\n\nLife-Carver Tzinik-Muz, we are egg-kin more than I could have realized. I do not seek your guardians as tools of war. In truth, I wished for the secrets of their design so I too could shape life from stone. Hubris is the color of my scales.\n\nI wish I could see these protectors first hand, but this old stone-shaper can proceed no farther into these old ruins. I leave my notes to any egg-kin who may follow in my steps. If you seek out Tzinik-Muz's vault, and the voskrona guardians' control stone, you must first release the three counterweights and face the temple's pendulums with courage.\n\nStone-Shaper Jazeez"] = "<Эти ветхие страницы покрыты выцветшими глифами на джеле. На полях видны примечания к переводу на тамриэльском языке, оставленные неким ваятелем столетия назад.>\n\n<Перевод> «Война выиграна, и все же я продолжаю усердно трудиться. Возможно, остальные правы. Если кто-то захочет узнать цвет одержимости, ему достаточно будет взглянуть на мою чешую. На мои ноющие, мозолистые когти, принявшие форму рукояток моих инструментов. Но я работаю не бесцельно.\n\nЯ вижу, как в глазах наших вождей разгорается новый голод. Теперь они видят в моих стражах не защитников, а оружие — инструменты для войны на чужих берегах. Но я создавал их не для этого. Теперь я посвящу остаток своей жизни тому, чтобы упрятать их в надежное место вместе с управляющим камнем. Чудеса этого храма, некогда свидетельствовавшие о нашем мужестве, теперь станут ловушкой для тех, кто ищет войны в мирное время».\n\n* * *\n<Примечание переводчика> Значит, хранилище, что я мельком видел в центре храма, таит в себе не саму зеленую жизнь, а созданные из нее формы. Воскрон. Это так странно — переводить слова аргонианина столь же древнего, каким себя ощущаю я. Сопереживать его мучениям, видя, как его глифы становятся все неровнее и грубее. Несомненно, тому виной ухудшающаяся подвижность плеча. Онемение запястья. Недуги, что требуют массажа в перерывах между письмом и у меня самого.\n\nРезчик жизни Тзиник-Муз, мы с тобой братья по кладке больше, чем я мог себе представить. Я ищу твоих стражей не для того, чтобы начать войну. По правде говоря, я жаждал узнать секреты их устройства, чтобы и самому создавать жизнь из камня. Моя чешуя — цвета гордыни.\n\nЯ бы очень хотел увидеть этих защитников своими глазами, но дальше мне, старому ваятелю, по этим руинам не пройти. Оставляю свои заметки родичам по кладке, что, возможно, однажды последуют по моим стопам. Если ты ищешь хранилище Тзиник-Муза и управляющий камень воскрон-стражей, то сперва освободи три противовеса и мужественно встреть маятники храма.\n\nВаятель Джазиз",
    ["I couldn't believe it when I heard that this place had ended up in Nirn. I convinced Sirilonwe that a research trip would provide a lot of information on vampires. Things the Mages Guild can use to combat any who posed a danger. This approach worked as I knew it would.\n\n* * *\nThe trip was uneventful and we made camp. I feel a strange sense of purpose? Energy? I am close. I know it. \nWe met another mage, Ormard. He has worked on a vampire compendium for decades, so it's no surprise that he knew of this place. He's a pleasant Nord fellow and even Sirilonwe warmed to him. \n\nOrmard and I have compared notes. His interest seems purely academic and he is eager to get into the place. Sirilonwe is still making some plans, not wanting to rush headlong into danger as she says. Ormard has been generous with the information he has on the Hall. It has sealed doors, different sections. Ormard says there are unique keys or tokens of some sort to open them. \n\n* * *\nOrmard and I decided to do an initial survey into the Hall. I confessed that my real interest was not so much the vampire denizens, but rather the Daedric artifacts rumored to be held within, and that I wanted to confirm that and maybe even bring one back to do my own research. I said Sirilonwe had strong opinions about what she calls relic hunting so I have not told her my true purpose. Ormard understood. He then confessed he found a break in the foundations! A small cave south of our camp. It will allow us to slip quietly into the place, as the main doors appear to be inaccessible after the place fell out of Coldharbour. \n\nWe're doing it. I am close. My heart is racing. Sirilonwe will be furious, but I am sure I can talk her around."] = "Я ушам своим не поверил, когда услышал, что это место теперь в Нирне! Я убедил Сирилонве, что исследовательская поездка даст нам массу сведений о вампирах. Таких, которые Гильдия магов сможет использовать для борьбы со всеми, кто представляет опасность. Я не сомневался, что это сработает, и оказался прав.\n\n* * *\nДобрались мы без происшествий и уже разбили лагерь. Я испытываю какой-то странный… не то азарт, не то прилив энергии. Я близок к цели и знаю это. \nМы встретили еще одного мага — норда по имени Ормард. Он не один десяток лет проработал над справочником по вампирам, так что неудивительно, что он знает об этом месте. Ормард оказался славным малым, и даже Сирилонве прониклась к нему симпатией. \n\nМы с Ормардом поделились сведениями. Им, похоже, движет чисто научный интерес, и ему не терпится попасть в Зал. Сирилонве все еще обдумывает план действий — не хочет, как она выражается, очертя голову бросаться навстречу опасности. Ормард рассказал мне о Зале все, что знает сам. Там есть запечатанные двери, которые ведут в разные помещения. Ормард говорит, что их можно открыть, но для этого нужны особые предметы — не то ключи, не то жетоны. \n\n* * *\nМы с Ормардом решились совершить первую вылазку в Зал. Я признался ему, что на самом деле меня интересуют не столько вампиры, сколько даэдрические артефакты, которые, по слухам, там хранятся, и что я хотел бы удостовериться в этом и, возможно, даже забрать один из них с собой — для исследований. Я сказал, что Сирилонве настроена категорически против того, что она называет «охотой за реликвиями», и что поэтому я не сказал ей о своих истинных намерениях. Ормард все понял. А потом признался, что нашел в фундаменте брешь! Небольшую пещерку к югу от нашего лагеря. Через нее мы сможем незаметно проникнуть в Зал. Главный вход, по-видимому, стал недоступен после того, как Зал покинул пределы Хладной Гавани. \n\nМы уже в пути. Цель близка. Мое сердце бешено колотится. Сирилонве будет в ярости, но я уверен, что смогу ее переубедить.",
    ["The Vos-Toh stone tablets offer a glimpse into Argonian death-dancers' beliefs in ancient times. I find them quite inspiring. They deserve extensive study. There are far more than just these simple words beneath the surface of the carefully carved glyphs.\n\n* * *\nVos-Toh of Song\n\nHail Sithis, the nothing of the Outer Darkness. No gentle truths placate fear. Embrace fear, for it is the song of the blood. We raise our voices to speak the words of the Void, the artistry of the Void, the truth of the Void.\n\n* * *\nVos-Toh of Dance\n\nHail Sithis, the serpent of chaos. Constantly moving. Never still. So we dance a ceaseless promenade. To one day slide and step and bounce joyously into the Void. To enact his will with perfect clarity and one day dance beside the Night Lord himself.\n\n* * *\nVos-Toh of Death\n\nHail Sithis, the ever-changing. What is consumed is restored. This is why we die. To one day soar beyond the reach of sun and stars, to enter the space between. To honor his will. To destroy what was and create what will be."] = "Каменные скрижали Вос-То позволяют получить представление о древних верованиях аргонианских танцующих со смертью. Я нахожу их весьма вдохновляющими и считаю, что они заслуживают тщательного изучения. За аккуратно вырезанными глифами скрывается нечто гораздо большее, нежели просто слова.\n\n* * *\nВос-То песни\n\nСлавься, Ситис, ничто внешней тьмы. Никаким лукавым истинам не унять страх. Откройся страху, ибо он есть песнь крови. Мы возвышаем наши голоса, дабы выразить слова Пустоты, искусство Пустоты, правду Пустоты.\n\n* * *\nВос-То танца\n\nСлавься, Ситис, Змей Хаоса. Вечно в движении. Ни на миг не замирающий. Подобно ему, мы шествуем в бесконечном танце, чтобы когда-нибудь сделать плавный шаг и радостно вознестись в Пустоту. Чтобы неукоснительно исполнять его волю и однажды танцевать рядом с самим Повелителем Ночи.\n\n* * *\nВос-То смерти\n\nСлава Ситису, перемены несущему. Что поглощено, то вновь вернется. Вот почему мы умираем. Чтобы однажды парить там, куда не дотянуться солнцу и звездам, чтобы попасть в пространство между ними. Чтобы чтить его волю. Чтобы разрушать былое и создавать грядущее.",
    ["Dark Adept Vairisse, \n\nThank you for the swift response regarding my inquiry as to the whereabouts of my estranged brother.\n\nI sent a trusted operative to your fortress. She should not cause any problems or interfere with your goals in the slightest. Her main objective is to keep me informed of my brother's travels. In short, she will not interfere with your work.\n\nWe both want my brother returned to his rightful place of imprisonment. Let us work together toward our mutual goal and so make Tamriel a safer realm for all who reside here—however long that may last."] = "Темный адепт Вайрисса! \n\nБлагодарю за быстрый ответ на мой запрос о местонахождении моего потерянного брата.\n\nЯ отправила в вашу крепость доверенного агента. Она не доставит вам никаких хлопот и никоим образом не помешает достижению ваших целей. Ее главная задача — информировать меня о передвижениях моего брата. Словом, в вашу работу она вмешиваться не будет.\n\nМы обе хотим, чтобы мой брат вернулся в свое законное место заключения. Так будем же вместе работать над достижением нашей общей цели и постараемся сделать Тамриэль безопаснее для всех его обитателей — сколько бы времени это ни заняло.",
    ["Tell me then, this Mani-Kai. I see a brittle thing, fresh from her egg. Eager as the lichen that grows wide without first placing roots. Do you trust her? Can she really hear the Hist?"] = "Расскажи мне про эту Мани-Кай. Я вижу хрупкое создание, едва вылупившееся из яйца. Нетерпеливое, как лишайник, что разрастается, не пустив корней. Ты доверяешь ей? Она действительно слышит хист?",
    ["How lucky are you to have walked through the mud alongside my teacher. You know then that the chimes I carry will help me interpret this tree's song. I only hope it will be enough to prove to these villagers that we are here to help."] = "Если тебе повезло пройти по грязи вместе с моим наставником, то ты знаешь, что эти подвески помогут мне истолковать песню дерева. Надеюсь, этого хватит, чтобы доказать местным, что мы пришли помочь.",
    ["There's a letter over there from Adrolir. It's addressed to you."] = "На песке лежит письмо от Адролира. Оно адресовано тебе.",
    ["Need to get more information from Ormard on these doors. Such elaborate mechanisms. Not mechanical. Not wholly magical. He said that he has a way to get past them, thanks to his various partners within the hall. Well, not partners, exactly. He continues to be a bit cagey with his information thus far.\n\nI hope Sirilonwe manages to catch up eventually. She should be here to write down all my observations."] = "Надо постараться побольше выведать у Ормарда об этих дверях. У них очень сложные механизмы. Это не механические устройства. Но и не совсем магические. Он сказал, что знает, как их открыть, благодаря своим многочисленным «связям» в Зале. Уж не знаю, какого они рода. Он не особенно вдается в подробности и говорит довольно уклончиво.\n\nНадеюсь, Сирилонве в конце концов удастся нас догнать. Она должна быть здесь, чтобы записывать мои наблюдения.",
    ["If the journals spoke true, their creators intended for them to act as defenders of their people. Let us hope that we have given the egg-kin of Xor-Hist the edge they need to face the necromancers."] = "Если дневники не лгут, их создатели хотели, чтобы они стали защитниками племени. Будем надеяться, что мы дали родичам по кладке в Зор-Хисте достаточное преимущество, чтобы противостоять некромантам.",
    ["Here as in Nirn? A whirlpool opened up on the azure seas. Captain One-Eye cackled and sailed us right in. Somehow she knew it would get us out of Coldharbour.\n\nNo one knew it would drop us from the sky. Or that Velehk Sain would dare to follow."] = "Здесь — это в Нирне? В лазурном море возник омут. Капитан Одноглазка расхохоталась и взяла курс прямо на него. Она как-то догадалась, что он выведет нас из Хладной Гавани.\n\nКто же мог знать, что он выплюнет нас прямо в небо! Или что Велек Сейн решится последовать за нами.",
    ["by Midconjuror Mirmal of the College of Rituals\n\nFew of Sunport's folk venture across the Solstice Range to visit the eastern half of our fair island. Yet this was not always the case. When House Corelanya first settled on these shores, our ancestors looked beyond the mountains and saw a land ripe for settlement. The fact that the Stone-Nest Argonians already lived there did little to deter the interest of proud kinlords and kinladies who desired a realm wide enough to suit their ambitions.\n\nWhen Kinlord Orlemar came to power in 1E 1017, he decided to act upon those ambitions. During his reign, vast tracts of land in eastern Solstice were parceled out to powerful nobles to settle or exploit as they wished. Yet no one seems to have informed the Stone-Nests about the arrangement. Centuries of strife between Elf and Argonian followed from the haughty kinlord's dealings.\n\nNaturally, Orlemar did not forget himself when handing out parcels of eastern Solstice. The kinlord claimed a magnificent estate in the northern part of the island, and named it Vaedinhill. There he commissioned the building of a great manor-house to serve as his summer palace, a luxurious retreat from the cares of the cares of the throne.\n\nThe cost of building Vaedinhill Manor nearly bankrupted the realm. Constructing such an extravagant palace in the wilds of eastern Solstice, far from the resources and workforce of Sunport, proved expensive indeed. But in 1E 1107, Kinlord Orlemar's palace was finally completed, a vision of fair Summerset amid a virgin wilderness. It was not to last.\n\nArgonian resistance to Kinlord Orlemar's policies was growing. While the kinlord enjoyed his palace for a time, travel to and from Vaedinhill became dangerous. Bands of Stone-Nest warriors began to shadow, and sometimes attack, travelers and wagons on the road to Vaedinhill. Orlemar found it increasingly difficult to maintain his court in the east. He did not visit the manor at all in the last ten years of his life, although he was laid to rest there.\n\nWhen open fighting broke out in 1E 1172, Stone-Nest warriors burned down Vaedinhill. During the troubled years that followed, Orlemar's successors could find neither the funds nor the forces needed to rebuild Vaedinhill. By the time Kinlady Torinwe concluded the Peace of Xor-Hist, House Corelanya had no interest in maintaining grand estates east of the mountains.\n\nOne can still visit the ruins of Vaedinhill to this day. Crumbling walls of white stone and weed-choked courtyards attest to the magnificence of Kinlord Orlemar's vision—and his folly."] = "Младший заклинатель Мирмал из Коллегии ритуалов\n\nМало кто из обитателей Санпорта отваживается пересечь хребет Солстиса, чтобы посетить восточную часть нашего прекрасного острова. Однако так было не всегда. Когда клан Кореланья впервые обосновался на этих берегах, наши предки устремили взгляд за горы и увидели земли, пригодные для освоения. Тот факт, что там уже жили аргониане из племени каменных-гнезд, едва ли мог остановить гордых кинлордов и кинледи, мечтавших о владениях достаточно обширных, чтобы удовлетворить их амбиции.\n\nВ 1017 году Первой эры, когда к власти пришел кинлорд Орлемар, он решил воплотить эти амбиции в жизнь. За время его правления обширные участки земли в восточной части Солстиса были розданы могущественным аристократам, получившим право селиться на этих землях или использовать их по своему усмотрению. Вот только, судя по всему, никто не удосужился сообщить об этом племени каменных-гнезд. Решения надменного кинлорда вылились в столетия вражды между эльфами и аргонианами.\n\nРазумеется, раздавая наделы на востоке Солстиса, Орлемар не забыл и о себе. Кинлорд заявил права на великолепное поместье в северной части острова и нарек его Вейдинхилл. Там он распорядился построить грандиозный особняк, который должен был стать его летней резиденцией — роскошным убежищем, где можно укрыться от бремени власти.\n\nЗатраты на строительство поместья Вейдинхилл едва не опустошили казну. Цена возведения столь экстравагантного дворца в глуши восточного Солстиса, вдали от ресурсов и рабочей силы Санпорта, оказалась непомерно высока. Но в 1107 году Первой эры дворец кинлорда Орлемара был наконец-то достроен и стал воплощением прекрасного Саммерсета посреди девственной природы. Впрочем, простоял он недолго.\n\nСопротивление аргониан политике кинлорда Орлемара неуклонно росло. Какое-то время он наслаждался своим дворцом, но поездки в Вейдинхилл и обратно вскоре стали небезопасны. Отряды воинов каменных-гнезд начали преследовать и атаковать путников и обозы на дороге к поместью. Орлемару становилось все труднее содержать свой двор на востоке. В последние десять лет своей жизни он так ни разу и не посетил поместье, однако похоронили его именно там.\n\nВ 1172 году Первой эры, когда начались открытые боевые столкновения, воины каменных-гнезд сожгли Вейдинхилл дотла. В последовавшие за этим смутные годы преемники Орлемара не смогли найти ни средств, ни сил для его восстановления. А к тому времени, когда леди Торинве заключила Зор-Хистский мирный договор, клан Кореланья и вовсе утратил всякий интерес к содержанию роскошных поместий к востоку от горного хребта.\n\nРуины Вейдинхилла можно посетить и по сей день. Обветшалые стены из белого камня и заросшие сорняками внутренние дворы служат немым свидетельством масштабных замыслов кинлорда Орлемара… и его причуд.",
    ["New Life is not for asking such dry questions, my friend! But allow me to indulge your curiosity. \n\nIn our village, we assume the role of Dakoi to help challenge ourselves with change, rather than resist and fight against the current."] = "Праздник Новой жизни — не время для столь сухих вопросов, <<player{друг мой/подруга}>>! Но я удовлетворю твое любопытство.\n\nЖители нашей деревни играют роль дакоя, чтобы перестать плыть против течения и помочь измениться себе и другим.",
    ["You're the Dakoi? So there's no fish?"] = "Дакой — это ты? Значит, никакой рыбы нет?",
    ["Exactly! As you noticed, Yesei takes pride in his skills. But that pride holds him back! Only with others can he challenge the greater currents.\n\nAnd you helped him overcome this challenge for New Life! For that, we shall feast on Dakoi!"] = "Ну конечно! Ты, наверное, <<player{заметил/заметила}>>, как Йесей гордится своим мастерством. Но эта гордость мешает ему двигаться вперед! Лишь с помощью других он сможет бросить вызов великим течениям.\n\nТы <<player{помог/помогла}>> ему пройти это испытание и начать Новую жизнь! Так что теперь мы вдоволь полакомимся дакоем!",
    ["Her Kinlady Torinwe of Corelanya, regarding with her favor the native rulers and tribes of Solstice and anxious to put to rest the strife between all the inhabitants of the island, wishes to secure for all impacted by the unrest peace, security, and good will between Elves and Argonians, which has been thus far exacerbated by the aforementioned conflict. \n\nTo this end she, alongside Tuintirrimo of the Corelanyan Guard and Pamaldawe of the Collegium, invite Mahei-Gei, representative for the Tide-Born of the western shores, and Tlekeus, speaking for the Stone-Nest of the eastern reaches, to concur upon the following articles and conditions. \n\nARTICLE THE FIRST\nAs long as all spoken-for inhabitants of Solstice adhere to the articles laid out in this document, they will lay down their arms against one another and vow to refrain from taking any hostile actions regarding ancestral or recent grievances. \n\nARTICLE THE SECOND\nAs set forth by this assembled congregation, the territories belonging to the Corelanya, Stone-Nest, and Tide-Born are hereby recognized as the sovereign land of the peoples thereof. Corelanya and Argonian alike agree not to encroach on the others' lands or impede them from crossing from one territory to another. Henceforth, no permanent dwellings shall be constructed in another's territory without express and written permission.\n\nARTICLE THE THIRD\nIn times when Solstice is threatened, we will temporarily waive the previous articles for the sake of mutual defense. \n\nWe signatories and assembled attendants, having been made fully aware of the provisions of this treaty, accept and enter into the full spirit of the stated agreement. \n\nCompleted at Xor-Hist in the year 1244 of the First Era."] = "Кинледи Торинве из клана Кореланья, в знак доброй воли по отношению к вождям и коренным племенам Солстиса и стремления положить конец распрям между обитателями острова, желает заключить мир между всеми враждующими сторонами и утвердить между эльфами и аргонианами добрососедские отношения, ранее омраченные уже упомянутыми распрями. \n\nС этой целью кинледи, а также Туинтирримо, представляющий гвардию Кореланья, и Памальдаве, выступающий от имени Общины, призывают Махея-Ге, представителя племени рожденных-приливом с западного побережья, и Тлекеуса, посланника племени каменных-гнезд с восточного побережья, заключить соглашение на условиях, изложенных ниже. \n\nПУНКТ ПЕРВЫЙ\nПри условии неукоснительного соблюдения всех пунктов настоящего договора все упомянутые в нем обитатели Солстиса обязуются сложить оружие и принести клятву прекратить все враждебные действия друг против друга, вызванные как старыми, так и недавними обидами. \n\nПУНКТ ВТОРОЙ\nСогласно решению, предложенному и принятому коллегиально, территории клана Кореланья, каменных-гнезд и рожденных-приливом отныне признаются их суверенными владениями. Как эльфы, так и аргониане отказываются от любых посягательств на чужие земли и обязуются не чинить препятствий путешественникам. Возведение каких бы то ни было постоянных построек на чужой земле без письменного дозволения ее владельца с сего дня строжайше запрещается.\n\nПУНКТ ТРЕТИЙ\nВ случае возникновения угрозы Солстису извне действие предыдущих пунктов настоящего договора может быть временно приостановлено для организации совместной обороны. \n\nМы, нижеподписавшиеся, удостоверяем, что в полной мере ознакомились с условиями сего договора и в присутствии свидетелей принимаем их. Договор вступает в силу немедленно. \n\nЗаписано в Зор-Хисте в 1244 году Первой эры.",
    ["Not a who. A what! Dakoi is a very special, sly … fish. Every New Life season, it greets our waters. It's said good fortune and growth comes to those who feast on this particular fish.\n\nBut, lately, it's proving difficult to catch."] = "Не кто, а что! Дакой — это такой особенный хитрый… Словом, это рыба. Каждый год на Праздник Новой жизни он приплывает в наши воды. Говорят, тому, кто его отведает, будут сопутствовать удача и процветание.\n\nНо в последнее время поймать его стало невероятно сложно.",
    ["Who's Dakoi?"] = "Дакоя? А кто это?",
    ["The fish has more tricks than a New Life Festival performer! I promised to reel it in for tonight's feast, but the Dakoi …. I refuse to be embarrassed any further!\n\nHunt the Dakoi for me, and I guarantee you'll get more than just good fortune."] = "У этой рыбы в запасе больше фокусов, чем у артиста на Празднике Новой жизни! Я пообещал поймать дакоя к сегодняшнему пиру, но он… Все, хватит. Не желаю больше позориться!\n\nПоймай дакоя вместо меня. Обещаю — получишь в награду не только удачу.",
    ["All right. Where did you last see the Dakoi?"] = "Ладно. Где ты видел дакоя в последний раз?",
    ["One only available during New Life. The Mudman is an effigy my kin and I construct to bless the new year with fertile growth across all of Tamriel.\n\nAnd … now I must do it without them."] = "Такого, какое можно получить лишь во время Праздника Новой жизни. Грязевик — это фигура, которую мы с моими родными лепим, чтобы новый год в Тамриэле выдался благодатным и плодородным.\n\nНо… в этом году мне придется лепить его без них.",
    ["Where are your kin?"] = "А где твои родные?",
    ["What kind of blessing?"] = "Какого благословения?",
    ["All right. What kind of mud do you need?"] = "Хорошо. Какая именно грязь вам нужна?",
    ["What is Anseilak, and how do I give them that?"] = "Что такое ансейлак? И как мне его дать?",
    ["And you're going to do this every day?"] = "И ты будешь проводить его каждый день?",
    ["It's not about falling. It's about getting up once again. And I know you can do that."] = "Упасть может каждый, это ничего. Главное — снова встать на ноги. И я знаю, что ты сможешь.",
    ["Hurl Snowballs at Targets"] = "Бросить снежки в цели",
    ["Has anyone ever told you Stone-Nests that your heads are as hard as rocks?"] = "Тебе когда-нибудь говорили, что у каменных-гнезд головы тверже камня?",
    ["Of course. A greataxe. A maul. A greatsword. A spear. A quarterstaff."] = "Конечно. С алебардой. Молотом. Двуручным мечом. Копьем. Посохом.",
    ["\"Release them, vile fiend!\"\n\nThere it is! Such strength. Such power! I feel like I could punch a horse! Has this always been within me? For better or worse, you've helped unleash a beast. Thank you."] = "«Отпусти ее, гнусный злодей!»\n\nВот оно! Какая сила! Какая мощь! Я готов коня остановить на скаку! Неужели я всегда был таким? К добру или к худу, но ты <<player{разбудил/разбудила}>> во мне зверя. Спасибо тебе.",
    ["Tell me more about your kin."] = "Расскажи мне о своих родных.",
    ["Because Orc forges turn out the best hammers, and I want our challenge to be fair and square. You can find one at the nearby smithy in the fortress. Everything should be ready when you return."] = "Потому что у орков получаются лучшие молоты, а я хочу, чтобы наше состязание было честным. Можешь взять один в кузнице здесь, в крепости. Когда вернешься, все уже будет готово.",
    ["What do you mean, tricks?"] = "Хитростей? Что ты имеешь в виду?",
    ["You mentioned you always organize this New Life festivity?"] = "Говоришь, ты всегда организуешь это празднование Новой жизни?",
    ["Return to Lanullin"] = "Вернуться к Лануллин",
    ["While Tibarr loves adventure, he … could never sink his claws into this particular activity. That's partly why this one organizes these festivities. \n\nIf Tibarr can't become a hero, then he can at least help others with his gold!"] = "Тибарр любит приключения, но… он так и не вонзил в это занятие когти. Отчасти поэтому он и организует это празднование.\n\nРаз уж Тибарру не суждено стать героем, он, по крайней мере, поможет своим золотом другим!",
    ["Deliver Baked Potato to Nenilon"] = "Доставить печеный картофель Ненилону",
    ["So you readily admit you were manipulated? How easily a little stone bends to the whims of wind and rain. You've wasted enough of my time. As the village's death-dancer, it is my duty to strike you down. Ready yourself."] = "То есть ты признаешь, что тобой манипулировали? Маленький камешек легко поддается капризам ветра и дождя. Хватит тратить мое время. Как танцующий со смертью этой деревни, я обязан убить тебя. Приготовься.",
    ["You met Master Hassavir? Impossible. Hmm …. But I wouldn't be surprised if his spirit still had ties here. He always wrote how Alik'r's deserts were his second home.\n\nMay our paths cross at least once."] = "Ты <<player{встретил/встретила}>> Хассавира? Но это невозможно. Хм… Впрочем, я не удивлюсь, если его дух все еще привязан к этим местам. Он всегда называл пустыню Алик’р своим вторым домом.\n\nНадеюсь, наши пути хотя бы раз пересекутся.",
    ["Deliver Banana Surprise to Geraldrim"] = "Доставить банановый сюрприз Геральдриму",
    ["Deliver Carrot Soup to Teliwe"] = "Доставить морковный суп Теливе",
    ["Craft Banana Surprise"] = "Приготовить банановый сюрприз",
    ["Craft Carrot Soup"] = "Приготовить морковный суп",
    ["Craft Baked Potato"] = "Приготовить печеный картофель",
    ["You need to gain Prince Naemon's trust, too. I would do it myself, but he knows me too well. \n\nHis chambers are through the door to our left. Now that I'm in the citadel, I can help with whatever task he gives you. So find me when you're done."] = "Тебе нужно втереться в доверие и к принцу Неймону. Я бы занялась этим сама, но он слишком хорошо меня знает.\n\nЕго покои — за дверью слева. Я могу помочь тебе с любыми поручениями, которые он даст. Как поговоришь с ним — приходи ко мне.",
    ["And how funny is it that the roots of their Hist tree forced them to abandon this temple. There is poetry to that, I am certain of it, but I have not an artist's patience."] = "Как ни забавно, этот храм им пришлось покинуть из-за корней хиста. В этом есть своя поэзия, я уверена, но я не обладаю терпением художника.",
    ["Did you see someone else here?"] = "Ты видела здесь кого-нибудь еще?",
    ["You must be Sirilonwe. The scout Mihnassi told me you lost your friend near the Ashbound Hall."] = "Ты, наверное, Сирилонве. Разведчица Минасси сказала, что ты потеряла своего друга возле Пепельного зала.",
    ["Soon after the Wall fell, a mage named Ormard came to us. He'd seen the Hall and offered to guide us here. Now I wake up and they're both gone. Come, I'll pay you to escort me while I find Terinvel. The vampires may no longer be securely locked away."] = "Вскоре после падения Стены к нам обратился маг по имени Ормард. Он сказал, что уже побывал в Зале, и пообещал отвести нас туда. Сегодня я проснулась — а оба моих спутника исчезли. Я готова тебе заплатить, если ты составишь мне компанию в поисках Теринвела. Вдруг запертые в зале вампиры выбрались наружу.",
    ["As I understand it, the Stone-Nest Argonians had numerous encounters with the Daedra when they first arrived on the island. After capturing and guarding the relic for generations, they gave it to us to protect. We must retrieve it."] = "Насколько я понимаю, после своего прибытия на остров племя каменных-гнезд сталкивалось с даэдра не раз и не два. Захватив реликвию, они много поколений хранили ее у себя, а затем отдали под защиту коллегии. Мы должны вернуть посох!",
    ["Return to Tibarr"] = "Вернуться к Тибарру",
    ["Give the Coin to the Beggar"] = "Отдать монету нищему",
    ["Steal a Coin from the Dragon's Hoard"] = "Украсть монету из сокровищ Дракона",
    ["For now, I'll rest. But it's likely Fenworine reported to some bigger Worm Cult nest. My plan is to meet Master Tanertor with an idea I had to bury them for good.\n\nAnd I'll do it with or without his help."] = "Пока что отдохну. Но Фенворин, скорее всего, уже доложила о случившемся в какое-нибудь крупное логово культа Червя. Так что я намерен обсудить с наставником Танертором свой план, который позволит покончить с ними раз и навсегда.\n\nЯ сделаю это — с его помощью или без.",
    ["Tell me more about Velehk Sain."] = "Расскажи мне о своей команде. Как вы все очутились в Хладной Гавани?",
    ["Well, we're a long way from Alten Corimont, aren't we, pirate?\n\nAh, seems so long ago. Can't even remember the sounds and smells of the swamp. Sight's still burning with those endless waves of azure plasm. But it's good to be back in my home plane."] = "Так ведь со времен Альтен-Коримонта много воды утекло, да, <<player{пират/пиратка}>>?\n\nЭх, давно это было! Я даже не помню ни звуков, ни запахов болота. Перед глазами до сих пор стоят бесконечные волны лазурной плазмы. Но я рада, что вернулась в родной мир.",
    ["Hunt Down the Dakoi"] = "Поймать дакоя",
    ["There was. Celbrim. We were all with Master Rolmedil when the attack happened. He went to go help others after the portal didn't open. I chose to stay and protect Rolmedil, but ….\n\nI was just as scared, too."] = "Да. Келбрим. Когда на нас напали, мы все были с наставником Рольмедилом. Портал не открылся, и Келбрим отправился помочь остальным. Я решила остаться и защищать Рольмедила, но…\n\nЯ страшно перепугалась.",
    ["You had no qualms about ending me. Prove to me that you can be just as ruthless toward this spy as you were toward me. Take the Eye to the room upstairs. No need to make a mess here.\n\nBring me proof when she's dead."] = "Меня ты <<player{убил/убила}>> без колебаний. Докажи, что со шпионкой можешь быть столь же <<player{решителен/решительна}>>. Отведи Глаз в комнату наверху. Ни к чему разводить грязь здесь.\n\nПринеси мне что-нибудь в доказательство того, что она мертва.",
    ["Thank you. I'm certain he would rather fling himself into the forge than open up to one of us. I'll try and mend things with Alma. We should've listened to her like you did."] = "Спасибо. Я уверена, что он скорее прыгнет в горн, чем откроется кому-то из нас. А я попробую помириться с Альмой. Нам следовало прислушаться к ней, как это <<player{сделал/сделала}>> ты.",
    ["Track the Dakoi"] = "Найти дакоя",
    ["Confront the Dakoi"] = "Поговорить с дакоем",
    ["Return to Yesei"] = "Вернуться к Йесею",
    ["Worm Cultists, Daedra, and minor undead already harass us at every turn. If Mannimarco succeeds at adding an army of ancient Argonians to his forces, we will be overwhelmed. Rescuing Vanus is vital, but you must stop their plan at the necropolis."] = "Культисты, даэдра и мелкая нежить и так уже донимают нас на каждом шагу. Если Маннимарко удастся пополнить свои войска армией древних аргониан, нас просто сметут. Спасти Вануса очень важно, но вы должны помешать их планам в некрополе.",
    ["Assist in Sculpting the Mudman"] = "Помочь слепить Грязевика",
    ["Gather Mud"] = "Собрать грязь",
    ["Return to Dailonda"] = "Вернуться к Дайлонде",
    ["Smear Mud on the Mudman"] = "Размазать грязь по Грязевику",
    ["Prove Your Strength"] = "Доказать свою силу",
    ["Take Hammer"] = "Взять молот",
    ["Return to Mahagog"] = "Вернуться к Махагогу",
    ["Break the Boulder"] = "Разбить валун",
    ["Gather Honeycomb for Garth"] = "Собрать медовые соты для Гарта",
    ["Gather Honeycomb"] = "Собрать медовые соты",
    ["Return to Garth"] = "Вернуться к Гарту",
    ["Place the Honeycomb on the Feeding Stone"] = "Положить медовые соты на камень-кормушку",
    ["Perform the Ritual of Anseilak"] = "Совершить ансейлак",
    ["Gather Seawater"] = "Собрать морскую воду",
    ["Travel to Motalion Necropolis"] = "Отправиться в некрополь Моталион",
    ["Complete the Ritual of Anseilak"] = "Завершить ансейлак",
    ["You didn't know. I suspect the Dark Elf was clueless, too. Ormard was a vampire imprisoned here. Before we fell, that is.\n\nBlind wandering won't help save the mortal. Go south, look for other brightly lit rooms. You'll find a map on the wall in one."] = "Так вы ничего не знаете… Думаю, тот темный эльф тоже был не в курсе. Ормард был одним из заточенных здесь вампиров. В смысле, до нашего падения.\n\nБлуждание вслепую не поможет вам спасти смертного. Идите на юг, ищите другие ярко освещенные залы. На стене в одном из них есть карта.",
    ["We can hope. Though my suspicions grow the deeper we get inside this prison. Who left these Aspects around for us to easily find? And why was Terinvel so eager to rush in without me?\n\nAnd finally, why am I friends with such an inconsiderate person?"] = "Будем надеяться. Хотя чем глубже мы пробираемся в эту тюрьму, тем сильнее меня одолевают вопросы. Кто оставил эти Аспекты на самом видном месте? И почему Теринвел так рвался вперед без меня?\n\nИ как меня вообще угораздило подружиться с таким безрассудным и бестактным эльфом?",
    ["I'll answer any questions, if you spare a potion or spell to aid me. \n\nYes, Ormard and a Dark Elf came through here. They did not notice me. They left in the direction of the courtyard."] = "Дайте мне зелье, чтобы облегчить мои страдания, или сотворите чары — и я отвечу на все ваши вопросы.\n\nДа, Ормард и темный эльф были здесь. Меня они не заметили. Направились в сторону внутреннего двора.",
    ["Thank you, stranger. I just want to leave this place. \n\nI had a family once, outside. I want to tell them what happened to me, if they're still alive."] = "Спасибо, <<player{незнакомец/незнакомка}>>. Теперь я хочу одного — уйти отсюда.\n\nКогда-то у меня были родные. Я хочу рассказать им о своей судьбе, если они еще живы.",
    ["Talk to the Lone Traveler"] = "Поговорить с одиноким путником",
    ["Fair warning—take even a sip and this partnership ends here and now. Bloodmite doesn't drink my blood, but he can find me just by taking a whiff of it. \n\nStrangely, it even helps relax him when he gets anxious."] = "Предупреждаю: выпьешь хоть глоток — я тебе больше не товарищ. Кровосос мою кровь не пьет, но может найти меня даже по слабому запаху.\n\nКак ни странно, этот запах даже помогает ему успокоиться, когда он нервничает.",
    ["Talk to the Hermit"] = "Поговорить с отшельником",
    ["I don't know. Such new feelings. Urges to dominate. Perhaps I'll take control of the University. Make all those pitiful academics praise me.\n\nYou should talk to Sirilonwe. I feel powerful thirst coming on."] = "Не знаю. Для меня это совершенно новые ощущения. Желание властвовать. Может, я захвачу университет. Заставлю этих жалких ученых восхвалять меня.\n\nТебе лучше поговорить с Сирилонве. Я чувствую, как во мне просыпается жажда.",
    ["Heh. Been around my crew so long I forgot it might unsettle folk.\n\nIt's a curse. One I took to save the souls of the Lost Fleet, press-ganged past death to serve in Coldharbour. Now, it's just who I am. No thought of changing back."] = "Ха! Я и забыла, что это может кого-то смутить. Команда-то давно привыкла.\n\nТак действует проклятие. Я приняла его, чтобы спасти души моряков Потерянного флота, которых заставили после смерти служить в Хладной Гавани. Меняться я не хочу. Так я теперь буду выглядеть всегда.",
    ["Dosu and I disagree on everything. Always have. But recently, we found something we agree on. Our feelings for one another.\n\nBut in how to consecrate this bond, we clearly disagree. Which courting custom would you find more meaningful, mainlander?"] = "Мы с Досу редко сходимся во мнениях. Так было всегда. Но недавно мы нашли почву для полного согласия. Это наши чувства друг к другу.\n\nОднако в том, как освятить наш союз, единства мы не достигли. Какой из обычаев ухаживания <<player{предпочел/предпочла}>> бы ты, <<player{гость/гостья}>> с большой земли?",
    ["Well, yes … it all happened so fast! With her dying breath, brave Golvyni threw herself back into the fray to save me. I … I am not worthy of such a noble deed … but I shall try to be."] = "Да, но… все случилось так быстро! Голвини, уже смертельно раненная, отважно бросилась в бой, чтобы спасти меня. Я… я не заслужил такой жертвы, но постараюсь сделать так, чтобы она была не напрасной.",
    ["How long have you and Golvyni worked together?"] = "Вы с Голвини долго работали вместе?",
    ["And stuff is an understatement! The Fellowship assaulted the fortress from two directions. I feared our failure to breach the gate would be our undoing, but you came through again.\n\nThe Worm Cult retreats north and the fort's power is shattered."] = "«И все прочее» — это ты про атаку крепости с двух сторон?! Я уж думал, что мы не сможем проломить ворота и все погибнем, но тут <<player{появился/появилась}>> ты.\n\nКульт Червя отступает на север, и крепость больше не представляет угрозы.",
    ["What? No, no, of course not! It's my business and mine alone. I planned to give her a portion of this job's gold as payment, plus a bit extra, and she agreed to relinquish her schematics.\n\nHmm. Perhaps her ailing mother knows where they are."] = "Что? Конечно нет! Это мой промысел — и только мой. Голвини причиталась доля награды за эту охоту. Я предложил добавить немного сверху, и она согласилась передать мне чертежи.\n\nГм… Может, ее хворая матушка знает, где они?",
    ["Oh, where has this day gone? Speaking of my business, I really must be getting back to it now.\n\nFriend, Golvyni is at peace, you have your gold. Let it go. I have bear-lizards to skin and an ailing mother to visit."] = "Ох, как время летит! Мне давно уже пора возвращаться к делам.\n\nГолвини обрела покой, а ты <<player{получил/получила}>> свое золото, <<player{друг/подруга}>>. Предлагаю на этом расстаться. Мне еще нужно снять чешую с медведей-ящеров и навестить кое-чью хворую матушку.",
    ["I was inspired enough by Dullard and his crew to write an epic poem based on their adventures.\n\nWhile doing a reading just now, he felt the need to interrupt and take issues with my creative liberties regarding his selection of bedfellows."] = "Этот тупица и его команда так меня вдохновили, что я сложил об их приключениях эпическую поэму.\n\nТолько что, когда я ее читал, он счел необходимым прервать меня и принялся оспаривать поэтические вольности, которые я позволил себе в описании его… ночных подвигов.",
    ["The words of the dead? Really? You're going to believe scribbles in a journal instead of a hunter with an impeccable reputation? No, I fail to see how I deceived you. I only asked for help.\n\nBut you just wanted to be difficult …."] = "В дневнике покойницы? Серьезно? Ты поверишь ее каракулям, а не охотнику с безупречной репутацией? Думай что хочешь, но я тебя не обманывал. Я лишь попросил помочь.\n\nНо ты <<player{решил/решила}>> устроить самодеятельность…",
    ["Gather Bait"] = "Добыть наживку",
    ["Are you afraid? Don't be. The cowardly are better to us dead than alive, and I will not hesitate to add your life to our power. \n\nSteel yourself. Soon, we rid this fortress of Naemon's presence!"] = "Боишься? Напрасно. Трусы полезнее нам мертвыми, чем живыми, и я без колебаний пущу твою жизненную силу на благо нашего дела.\n\nСоберись. Скоро и духу этого Неймона в крепости не будет!",
    ["Just one, but it requires a favor. I know, you've done plenty already. But could you find a way in, fix the platforms, maybe dispel a few wards? Meridia does love her magic traps! Then we can head inside.\n\nEasy stuff. You got this, right?"] = "Одна есть, но мне понадобится твоя помощь. Конечно, ты и так уже много <<player{сделал/сделала}>>. Но не <<player{мог/могла}>> бы ты пробраться внутрь, починить платформы… и, возможно, развеять парочку оберегов? Меридия обожает магические ловушки! Тогда мы сможем попасть внутрь.\n\nДело пустяковое. Ты ведь справишься, верно?",
    ["You were there? Perhaps you met Er-Jaseen. Crown and beard of black spines. Swishing tail. A kindness in his eyes."] = "Ты <<player{был/была}>> там? Может, ты <<player{видел/видела}>> Эр-Джасина? У него гребень и борода из черных шипов и мощный хвост, а глаза добрые.",
    ["Er-Jaseen. He helped Argie escape the Wailing Prison. I meant for him to escape with me, but he stayed behind to help the others. \n\nThere were so many others. I don't know if he escaped. I should never have let him stay behind."] = "Его зовут Эр-Джасин. Он помог Арги бежать из тюрьмы Стенаний. Я звала его с собой, но он остался, чтобы помочь остальным.\n\nИх было так много… Не знаю, удалось ли ему бежать. Зря я позволила ему остаться.",
    ["Walked right into that one, didn't I?\n\nIf only Salvus was here. You'd have him in stitches. No mirrors on the Spriggan. Heh."] = "Я сам напросился, да?\n\nЭх, жаль, Салвуса с нами нет. Он бы со смеху лопнул. Зеркал на «Сприггане» нету. Ха.",
    ["Find the Oblivion Boulder"] = "Найти валун из Обливиона",
    ["Without a single one of our crew seeing you? Hmm. Maybe you are the right sort to take out that observer.\n\nTry not to disappoint me, all right?"] = "И никто тебя не заметил? Гм… Может, тебе и удастся устранить наблюдателя.\n\nНе разочаруй меня, <<player{понял/поняла}>>?",
    ["Remember Camlorn. Your dad. Alinon. The people there."] = "Вспомни Камлорн. Своего отца. Алинона. Всех, кто там живет.",
    ["Remember Shornhelm. Sneaking into Northpoint. Your … antics."] = "Вспомни Шорнхельм. Как мы пробирались в Нортпойнт. Свои… выходки.",
    ["Remember Coldharbour. How we fought alongside King Dynar. How we stopped Molag Bal."] = "Вспомни Хладную Гавань и наше сражение вместе с королем Динаром. Вспомни, как мы остановили Молага Бала.",
    ["I have gone to great lengths to define my authority and the boundaries of the prince's. No one will confuse them again.\n\nIf there are any issues, come to me or one of my aides. We will be more than pleased to clarify who is in charge here."] = "Я приложила много усилий для того, чтобы четко очертить круг своих полномочий — и полномочий принца. Нарушать эти границы я не позволю.\n\nЕсли принц начнет командовать — обратись ко мне или к кому-нибудь из моих помощников. Мы с радостью напомним, кто тут главный.",
    ["I am, of course, limited by the bargains I strike with prevailing Princes, but yes. I am a Daedra with many forms. But I do not use this gift to seek power.\n\nOnce I have experienced all Oblivion has to offer, I will finally know who I am."] = "Разумеется, сделки, что я заключаю с князем того или иного царства, накладывают некоторые ограничения, но да. Я даэдра с тысячью обличий. Однако я не использую этот дар ради обретения власти.\n\nКогда я испытаю все, что только есть в Обливионе, то наконец пойму, кто я есть.",
    ["I can spare a few moments before I resume my preparations to return to the mainland. You've more than earned the right to ask questions, champion."] = "Я могу уделить тебе пару минут, прежде чем вернусь к сборам перед возвращением на большую землю. Ты с лихвой <<player{заслужил/заслужила}>> право задавать вопросы, <<player{герой/героиня}>>.",
    ["Why would Molag Bal make vampires fight each other?"] = "Но зачем Молагу Балу стравливать вампиров?",
    ["Looking for inspiration! I heard all about the goings-on here and I tried to get here as fast as I could.\n\nSeems like most of the good stuff happened without me here to witness. I'm trying to get what information I can so the trip isn't a total loss."] = "Ищу вдохновение! Я наслушался рассказов о здешних событиях и поспешил сюда со всех ног.\n\nНо, похоже, все самое интересное я пропустил. Теперь вот пытаюсь собрать хоть какой-то материал, чтобы поездка не оказалась совсем уж напрасной.",
    ["As vampires age, they gain strength. Physically and magically. And coming here breaks your morality after a while. The kind don't grow old.\n\nElder prisoners force the young to protect them. At threat of exsanguination."] = "С возрастом вампиры становятся сильнее. Как в физическом, так и в магическом плане. А пребывание здесь потихоньку разрушает моральный облик. Мягкосердечные не выживают.\n\nСтарейшие узники заставляют молодых защищать их. Под угрозой обескровливания.",
    ["As good as I can be after whatever that was in the temple. Did Vanus fill you in? I tried to avoid him, but he's surprisingly limber for a centuries old mage.\n\nBut we're not here to talk about Vanus. Unless you … want to talk about Vanus?"] = "Ну да — насколько это возможно после того, что произошло в храме. Ванус тебе рассказал? Я пытался избежать разговора, но для мага, которому сотни лет, он на удивление прыткий.\n\nВпрочем, мы тут не для того, чтобы говорить о Ванусе. Или ты… хочешь о нем поговорить?",
    ["Observe Sirilonwe's Magic"] = "Наблюдать за магией Сирилонве",
    ["Search the Broken Walkway"] = "Осмотреть разбитый проход",
    ["Perform a Dance in the Mud"] = "Исполнить танец в грязи",
    ["Use any Musical Emote"] = "Использовать любую музыкальную эмоцию",
    ["Player Logged Out"] = "Игрок вышел из игры",
    ["Player Died"] = "Игрок погиб",
    ["Notes written by Vanus Galerion to Gabrielle and smuggled out of his prison by Baar-Jasa."] = "Записка Вануса Галериона для Габриэль, тайно вынесенная из места его заточения Бар-Джасой.",
    ["Not precisely, but they know to head to the portal gates in emergencies. However, they need a keystone to activate them and return to Sunport.\n\nTake my keystone. Activate the portals and save my apprentices. I promise to reward you for your efforts."] = "Точно не знаю, но они знают, что в случае опасности нужно спешить к порталам. Однако без камня-ключа они не смогут открыть их и вернуться в Санпорт.\n\nВот мой ключ. Открой порталы и спаси учеников. Я награжу тебя за помощь.",
    ["Captain One-Eye. She'll know what to do. Help us, and I'll make sure she cuts you in for a share of our plunder.\n\nThe ships came down by those cliffs to the north. I think, if the captain made it, that is where she'll rally the crew."] = "Капитан Одноглазка! Она знает, что делать. Помоги нам — и каджит проследит, чтобы ты <<player{получил/получила}>> свою долю добычи.\n\nКорабли вывалились из портала вон у тех скал к северу отсюда. Если капитан уцелела, команду она будет собирать там.",
    ["You can't find anyone to help you out?"] = "Никто не хочет тебе помогать?",
    ["I'll help. What exactly do you need me to do?"] = "Конечно, я помогу. Что именно надо сделать?",
    ["You made all this food for someone else?"] = "Ты приготовила всю эту еду для кого-то другого?",
    ["A lot of someones, actually. It's an offering for elders in our community. A chance to pay them back for years of wisdom this New Life, but I'm struggling to find anyone to help me with the final preparations."] = "Да, и не для одного, а для многих. Это дар старейшинам нашей общины. Я хочу отблагодарить их за годы мудрости и поздравить с Праздником Новой жизни, но не могу найти никого, кто помог бы мне с последними приготовлениями.",
    ["Everyone's busy with something, from the Three Banners War to a knotted ball of their own problems. And some simply don't care.\n\nSince you seem even the least bit interested, would you be willing to help me? For New Life, and for pay, of course."] = "У всех полно забот — начиная с Войны трех знамен и кончая запутанным клубком собственных проблем. А некоторым просто все равно.\n\nРаз уж ты <<player{проявил/проявила}>> интерес, может, согласишься мне помочь? Ради Праздника Новой жизни и, конечно, за вознаграждение.",
    ["A little help for New Life would be appreciated …."] = "Небольшая помощь в честь Праздника Новой жизни пришлась бы очень кстати…",
    ["A coin swiped from the hoard of Rawl'kha's Dragon as part of the New Life Festival."] = "Монета, украденная из сокровищ Дракона Рол’ки во время Праздника Новой жизни.",
    ["Dragon's Coin"] = "Монета Дракона",
    ["Tricky in what way?"] = "Непростой? Почему?",
    ["All right. Where can I find the Dragon?"] = "Ладно. Где мне найти Дракона?",
    ["Rawl'kha's Dragon?"] = "У Дракона Рол’ки?",
    ["Tibarr apologizes. This one did not mean to alarm. We are in no danger. It is our New Life tradition to steal the Dragon's treasure and distribute it to the needy. Tibarr always organizes it!\n\nHowever, this season's challenge has been … tricky."] = "Тибарр просит прощения. Он не хотел тебя напугать. Никакой опасности нет. Просто у нас такой обычай праздновать Новую жизнь. Мы крадем сокровища Дракона и раздаем их нуждающимся. Тибарр всегда это организует!\n\nВот только в этом году задачка вышла… непростой.",
    ["Now, that would spoil the fun! This New Life tradition seeks to help us sharpen both our minds and our claws. Will you try to abscond with the Dragon's hoard?\n\nTibarr promises a portion of the gold will be yours to keep!"] = "Ну нет, это же испортит всю забаву! Этот обычай Новой жизни помогает нам оттачивать не только когти, но и ум. Не желаешь ли попытаться похитить сокровища Дракона?\n\nТибарр обещает, доля золота достанется и тебе!",
    ["Who will face Rawl'kha's Dragon for New Life?"] = "Кто отважится встретиться с Драконом Рол’ки в честь Праздника Новой жизни?",
    ["Fresh mud collected for Dailonda's Mudman."] = "Свежая грязь, собранная для Грязевика Дайлонды.",
    ["Mudman Mud"] = "Грязь для Грязевика",
    ["What's making it so difficult?"] = "В чем состоит сложность?",
    ["All right. Where can I find the Dakoi?"] = "Ладно. Где мне найти дакоя?",
    ["That clever little Dakoi can't elude me forever."] = "Этот проныра дакой не сможет ускользать от меня вечно.",
    ["Forged by Orsimer Orcs to break boulders for Betnikh's Boon in the New Life Festival."] = "Выкован орками-орсимерами для разбивания валунов ради Благословения Бетника на Празднике Новой жизни.",
    ["Orsimer Hammer"] = "Орсимерский молот",
    ["Gone to spread their roots beyond Grahtwood. My home is here with my followers, but with our numbers reduced, we struggle to complete the Mudman.\n\nI believe your path through the Green has led you here. Help us gather mud and you'll be rewarded."] = "Пустили корни за пределами Гратвуда. Я осталась здесь, со своими последователями, но нас слишком мало, чтобы завершить Грязевика.\n\nЯ убеждена, что это Зеленый Лес привел тебя сюда. Помоги нам набрать грязи — и получишь награду.",
    ["Let our prayers bring the Mudman to life!"] = "Пусть наши молитвы вдохнут в Грязевика жизнь!",
    ["A sweet and succulent honeycomb. Surely this will lighten the mood of the hermit's bear, Garth."] = "Сладкие и соблазнительные медовые соты. Они наверняка поднимут настроение Гарту, медведю отшельника.",
    ["Succulent Honeycomb"] = "Соблазнительные медовые соты",
    ["You want me to smash a boulder?"] = "Ты хочешь, чтобы я <<player{разбил/разбила}>> валун?",
    ["I accept your challenge. What kind of boulder do you have in mind?"] = "Я принимаю вызов. Какой валун мне разбить?",
    ["What sort of competition?"] = "Что за состязание?",
    ["Just the best New Life has to offer! We haul in big boulders and smash them. Whoever breaks a boulder into the smallest bits with one strike claims a boon of good health until the next New Life.\n\nAnd with bragging rights, of course."] = "Самое лучшее состязание Новой жизни! Мы таскаем огромные валуны и разбиваем их. Тот, кто одним ударом расколет свой камень на самые мелкие кусочки, получит благословение крепкого здоровья до следующего праздника.\n\nНу и право хвастаться, само собой.",
    ["Not just any boulder! Let's make it interesting and find one that's truly worthy of Betnikh's Boon! Something none of these losers could ever hope to chip or crack. I'll even throw in something extra for the winner. \n\nSo, friend, what do you say?"] = "И не просто валун! Чтобы всем было интересней, мы найдем валун, достойный Благословения Бетника! Такой, чтобы эти недотепы и поцарапать не смогли. А я победителю еще и немного золотых сверху накину!\n\nНу что, <<player{друг/подруга}>>, ты с нами?",
    ["Can no one provide a proper challenge this New Life?"] = "Неужто в этом году у меня так и не будет достойных соперников?",
    ["Why is Garth in a bad mood?"] = "Почему у Гарта дурное настроение?",
    ["All right. Where can I find some honeycomb?"] = "Ладно. Где мне взять медовые соты?",
    ["Garth wants to eat Tamriel?"] = "Гарт хочет проглотить весь Тамриэль?",
    ["Eat, destroy, same difference. The Skaals in the village don't believe it, but Garth has a piece of the All-Maker in him. And it's his jolly mood during New Life that determines Tamriel's fate for the coming year!\n\nRight now, it's not looking good."] = "Проглотить, уничтожить — какая разница. Скаалы из деревни в это не верят, но в Гарте живет частичка Все-Создателя. И именно от его настроения на Праздник Новой жизни зависит, что ждет Тамриэль в предстоящем году!\n\nА сейчас оно у него не слишком хорошее.",
    ["Ask the fool in his belly the next time you meet him. At least he was calm while I juggled and … wait.\n\nHoneycomb! That will brighten Garth's mood! Bring him some while I keep juggling and we may just save Tamriel and New Life yet!"] = "Спроси дурака у него в брюхе, когда в следующий раз его встретишь. По крайней мере, пока я жонглировал, он вел себя смирно и… Погоди-ка.\n\nМедовые соты! Вот что поднимет Гарту настроение! Принеси ему сот, пока я жонглирую, и, может статься, мы еще спасем и Тамриэль, и Новую жизнь!",
    ["What's wrong, Garth? My juggling used to soothe you."] = "Что с тобой, Гарт? Раньше мое жонглирование тебя успокаивало.",
    ["Despite its seemingly ancient make, this water skin shows no signs of wear and tear."] = "Несмотря на солидный возраст, этот мех для воды совсем не износился.",
    ["All right. I'll help you perform Anseilak for the Yokudan mages."] = "Хорошо. Я помогу тебе совершить ансейлак для магов Йокуды.",
    ["No. What're you on pilgrimage for?"] = "Нет, я не <<player{паломник/паломница}>>. А что за паломничество ты совершаешь?",
    ["Withered Water Skin"] = "Выцветший мех для воды",
    ["If only I could survive the journey. Every New Life, we give Anseilak to the fallen Yokudans so that their spirits may rest peacefully. However, Yokudan mages are ignored for their involvement in magic.\n\nTraveler. Will you give them Anseilak?"] = "Если б я только мог сам пройти этот путь… Каждую Новую жизнь мы воздаем ансейлак павшим йокуданцам, чтобы их души обрели покой. Но маги Йокуды всегда остаются в тени — их искусства многие чураются.\n\n<<player{Путник/Путешественница}>>, может быть, ты дашь им ансейлак?",
    ["Forgive me. It is a ritual where we gather seawater that once touched Yokuda's lands. We then perform it for the fallen mages resting at Motalion Necropolis, bringing them peace.\n\nKnow your efforts will be repaid in full."] = "Прошу прощения. Это ритуал, во время которого мы собираем морскую воду — ту, что некогда омывала берега Йокуды. Этой водой мы совершаем обряд над павшими магами в некрополе Моталион и даруем успокоение их душам.\n\nЗнай, твои старания не останутся без награды.",
    ["I must bring peace to the rest of the Yokudans."] = "Я должен помочь другим йокуданцам обрести покой.",
    ["Water that once touched the ancient land of Yokuda, now sunken deep beneath the sea."] = "Вода, что некогда омывала древние земли Йокуды, теперь ушла на самую глубину моря.",
    ["Fresh Seawater"] = "Свежая морская вода",
    ["You prepared a hearty, rich baked potato for Nenilon. Deliver it to him near the banks of Toothmaul Gully as an offering for New Life."] = "Вы приготовили сытный и ароматный печеный картофель для Ненилона. Отправляйтесь к Оврагу Зубодробителей и вручите ему угощение в честь Праздника Новой жизни.",
    ["I learned that Lanullin is leading an effort to give back to esteemed High Elf elders in her community. However, it seems they're shorthanded. I agreed to help her however I can."] = "Я <<player{узнал/узнала}>>, что Лануллин хочет отблагодарить старейшин — высоких эльфов своей общины. Но, похоже, она не справляется одна. Я <<player{согласился/согласилась}>> помочь ей чем смогу.",
    ["Giving back? How?"] = "Отблагодарить? Каким образом?",
    ["All right. I'll help Lanullin in Auridon."] = "Хорошо, я помогу Лануллин на Ауридоне.",
    ["I'm interested. Tell me more."] = "Звучит интересно. Расскажи подробнее.",
    ["Nenilon's Baked Potato Offering"] = "Печеный картофель в дар Ненилону",
    ["Here's a New Life festivity that strikes a chord in me. Lanullin leads an earnest effort to give back to High Elf elders this season, especially those who shared their wisdom with her community."] = "Есть одно празднество, которое меня особенно трогает. В этом году Лануллин задумала отблагодарить старейшин — высоких эльфов, особенно тех, кто делился мудростью с ее общиной.",
    ["By rattling pots and pans and cooking up something delicious! A shame, though. I hear she doesn't have enough help to make offerings for all the elders she hopes to provide for.\n\nCould you lend them a hand in Auridon, friend?"] = "Она вовсю гремит котелками и сковородками, готовя разные вкусности! Но, как я слышал, у нее не хватает рук, чтобы успеть приготовить дары всем старейшинам, которых она хочет почтить.\n\nНе отправишься ли ты на Ауридон, чтобы помочь ей, <<player{друг/подруга}>>?",
    ["Help support Auridon's elders for New Life!"] = "Помоги поддержать старейшин Ауридона в честь Праздника Новой жизни!",
    ["You prepared a sweet and tempting banana surprise for Geraldrim. Deliver it to him near the Ezduiin's Ruins as an offering for New Life."] = "Вы приготовили сладкий и аппетитный банановый сюрприз для Геральдрима. Отправляйтесь к Эздуину и вручите ему угощение в честь Праздника Новой жизни.",
    ["A wealthy Khajiit seems to be hosting a game for New Life that involves hoards of gold and a grand opponent guarding it. To learn more, I need to speak to Tibarr, the organizer for this festivity."] = "Богатый каджит устраивает в честь Праздника Новой жизни игру, в которой фигурируют сокровища и их могучий страж. Чтобы узнать подробности, мне нужно поговорить с Тибарром — организатором этого празднества.",
    ["Tell me about this guardian."] = "Расскажи мне об этом страже.",
    ["All right. I'll speak to Tibarr in Rawl'kha."] = "Ладно. Я поговорю с Тибарром в Рол’ке.",
    ["Geraldrim's Banana Surprise Offering"] = "Банановый сюрприз в дар Геральдриму",
    ["I hesitate to mention due to the danger, but you seem the daring sort. A wealthy Khajiit in Rawl'kha has put a hoard of gold on the line—if you can overcome its guardian."] = "Даже не знаю, стоит ли рассказывать, уж слишком это опасно. Но ты, похоже, не робкого десятка. Один богатый каджит из Рол’ки поставил на кон целую гору золота — оно достанется тому, кто одолеет стража этих сокровищ.",
    ["New Life is about surprises, too, my friend! I'll let Tibarr be the one to reveal his grand scheme to you.\n\nBut a word of caution—watch your step when you face the guardian!"] = "Новая жизнь — это еще и время сюрпризов, <<player{друг мой/подруга}>>! Пусть Тибарр сам откроет тебе свой грандиозный замысел.\n\nТолько помни: когда встретишься со стражем, будь начеку!",
    ["Here's a New Life festivity for those who love a challenge!"] = "Празднование Новой жизни для тех, кто любит испытания!",
    ["You prepared a warm, nourishing carrot soup for Teliwe. Deliver it to her at the College of Aldmeri as an offering for New Life."] = "Вы приготовили горячий и наваристый морковный суп для Теливе. Отправляйтесь к Коллегии альдмерской благопристойности и вручите ей угощение в честь Праздника Новой жизни.",
    ["Anicus mentioned an angler called Yesei trying to catch a fabled Dakoi fish for New Life. He thinks he needs help, and that I should speak to him."] = "Аник рассказал мне о рыбаке по имени Йесей, который пытается поймать дакоя — легендарную рыбу Праздника Новой жизни. Аник считает, что рыбаку нужна помощь и что мне следует с ним поговорить.",
    ["Interesting. Tell me more."] = "Интересно. Мне хотелось бы знать больше.",
    ["All right. I'll find Yesei in Stormhold."] = "Ладно. Я найду Йесея в Стормхолде.",
    ["Teliwe's Carrot Soup Offering"] = "Морковный суп в дар Теливе",
    ["Let me tell you about the murky waters of Stormhold. Nearly fell in when a poor angler rushed past me in pursuit of the fabled Dakoi fish.\n\nIt's a strange way to celebrate New Life, but that's what makes it special!"] = "Позволь, я расскажу тебе про мутные воды Стормхолда. Я чуть в них не свалился, когда мимо меня промчался несчастный рыбак — он гнался за легендарной рыбой, дакоем.\n\nНемного странный способ праздновать Новую жизнь, но в нем тоже есть своя прелесть!",
    ["The Dakoi only appears during the New Life season. Poor Yesei has been chasing it all over Stormhold. Whoever catches it gets a year of good luck, and Yesei could really use some.\n\nIf you don't mind getting a little wet, go help him out!"] = "Дакой появляется только во время Праздника Новой жизни. Бедняга Йесей гонялся за ним по всему Стормхолду. Того, кто его поймает, ждет удачный год, а Йесею удача очень нужна.\n\nЕсли ты не против немного промокнуть, отправляйся к нему на выручку!",
    ["Will you be the one to hook Stormhold's fabled Dakoi this season?"] = "А вдруг именно тебе в этом году повезет подцепить на крючок дакоя — легендарную рыбу из Стормхолда?",
    ["Prepare carrot soup and deliver it to Teliwe at the College of Aldmeri as an offering for New Life."] = "Приготовьте морковный суп и отнесите это угощение в честь Праздника Новой жизни Теливе. Она у Коллегии альдмерской благопристойности.",
    ["In Elden Root, Dailonda and her followers are constructing a Mudman effigy to bless Tamriel, but they need a hand. I agreed to help her however I can."] = "Дайлонда и ее последователи в Элден-Руте лепят фигуру Грязевика, чтобы благословить Тамриэль, но им нужна помощь. Я <<player{согласился/согласилась}>> помочь чем смогу.",
    ["Mudman effigy? She's sculpting with mud?"] = "Грязевик? Она лепит фигуру из грязи?",
    ["I'll head to Elden Root and help Dailonda."] = "Я отправлюсь в Элден-Рут и помогу Дайлонде.",
    ["This one's a bit messy. Dailonda's kin usually help her with the sculpting for New Life, but they all recently departed Elden Root's branches for newer trees.\n\nNow, it's only her, a few of her followers, and their Mudman effigy."] = "Предупреждаю, будет грязно. Обычно лепить фигуру на Праздник Новой жизни Дайлонде помогали ее родные, но не так давно все они покинули ветви Элден-Рута и переселились на новые деревья.\n\nОсталась только она сама, несколько ее последователей да их Грязевик.",
    ["Like I said, messy. When completed, the Mudman bestows its blessing upon Tamriel. But poor Dailonda also believes that bad luck follows if the sculpture isn't finished.\n\nSo, are you up for frolicking in the mud and lending a hand?"] = "Я же сказал, будет грязно. Когда Грязевик будет закончен, он дарует Тамриэлю свое благословение. Но бедняжка Дайлонда уверена, что, если фигуру не закончить, это может навлечь беду.\n\n<<player{Готов/Готова}>> немного побарахтаться в грязи ради доброго дела?",
    ["Who doesn't mind a little dirt for a New Life blessing?"] = "Кто не против немного испачкаться ради благословения Новой жизни?",
    ["Prepare a baked potato and deliver it to Nenilon near the banks of Toothmaul Gully as an offering for New Life."] = "Приготовьте печеный картофель и отнесите это угощение в честь Праздника Новой жизни Ненилону. Он у Оврага Зубодробителей.",
    ["I learned that a group of Orcs in Betnikh celebrate New Life by breaking boulders for a special boon. To participate, I need to speak to Mahagog, their leader."] = "Я <<player{узнал/узнала}>>, что орки на Бетнике празднуют Новую жизнь, разбивая валуны ради некоего особого благословения. Чтобы принять участие в этом состязании, мне нужно поговорить с Махагогом, их вожаком.",
    ["What's Betnikh's Boon?"] = "Что за Благословение Бетника?",
    ["All right. I'll talk to Mahagog at Stonetooth Fortress."] = "Хорошо, я поговорю с Махагогом в крепости Каменного Зуба.",
    ["Orcs over in Betnikh compete for Betnikh's Boon in a contest of strength every New Life. The competition involves physical strength, keen reflexes, and huge boulders!"] = "Каждый год на Новую жизнь орки на Бетнике бьются за Благословение Бетника, состязаясь в силе. Такое состязание требует могучей хватки, молниеносной реакции и умения управляться с огромными валунами!",
    ["A favor or benefit of some kind. You'd have to ask Mahagog. He's leading the contest. You can find him at Stonetooth Fortress in Betnikh.\n\nFair warning—he loves competition and hates to lose."] = "Какое-то преимущество или выгода. Спроси лучше у Махагога. Это он руководит состязанием. Он сейчас в крепости Каменного Зуба на Бетнике.\n\nНо учти: он обожает соревноваться и ненавидит проигрывать.",
    ["If you've got muscles, I've got a New Life festivity for you!"] = "Если ты не прочь размяться, могу предложить отличное празднество!",
    ["Prepare a banana surprise and deliver it to Geraldrim near the Ezduiin's Ruins as an offering for New Life."] = "Приготовьте банановый сюрприз и отнесите это угощение в честь Праздника Новой жизни Геральдриму. Он у руин Эздуин.",
    ["A lone traveler seems to be asking for help making a pilgrimage. Supposedly, it can help bring peace to the fallen Yokudans during New Life. I agreed to help however I can."] = "Одинокая путешественница просит меня помочь совершить паломничество. По-видимому, во время Праздника Новой жизни это может помочь павшим йокуданцам обрести покой. Я <<player{согласился/согласилась}>> помочь в меру своих возможностей.",
    ["Any reason why nobody wants to help them?"] = "Почему же никто не хочет помочь?",
    ["All right. I'll find them in Sentinel."] = "Хорошо, я найду того путника в Сентинеле.",
    ["This one I haven't been able to check personally. Whispers carried by Sentinel's winds tell of a lone traveler seeking help from passersby for New Life. Something about a pilgrimage to bring fallen Yokudans peace.\n\nAlas, the pleas fall on deaf ears."] = "Сам я в этом празднестве пока не участвовал. Но ветра Сентинеля донесли до меня слухи об одиноком путнике, что просит прохожих о помощи в честь Новой жизни. Речь идет о паломничестве, призванном помочь павшим йокуданцам обрести покой.\n\nУвы, пока что все мольбы остаются без ответа.",
    ["Who can say? I hear Redguard have peculiar notions regarding the dead, so perhaps that's part of it.\n\nIf you can deal with hot sand and biting winds, seek them out in Sentinel. It would be a shame if their approach to New Life didn't succeed."] = "Кто знает? Говорят, у редгардов довольно странные убеждения относительно мертвых. Может, в этом все и дело.\n\nЕсли не боишься горячего песка и жгучего ветра, отправляйся в Сентинель. Будет жаль, если этот способ праздновать Новую жизнь не увенчается успехом.",
    ["New Life and long dead in Sentinel! Ask me for details!"] = "Новая жизнь и давно усопшие в Сентинеле! Подходи, кому интересно!",
    ["Many Nords seem to describe a hermit claiming that his pet bear's mood is important this New Life. I should speak to him to learn more about what he needs."] = "Многие норды рассказывают об отшельнике, который утверждает, что настроение его ручного медведя крайне важно для Праздника Новой жизни. Надо поговорить с ним и узнать, в чем дело.",
    ["His bear?"] = "Его медведь?",
    ["All right. I'll head to the Rift and talk to the hermit."] = "Хорошо, я отправлюсь в Рифт и поговорю с отшельником.",
    ["Here's a bizarre one I haven't had a chance to check on yet. A crazed hermit in the Rift proclaims this will be the last New Life. That the end of days are upon us. Heh, what else is new?\n\nBut here's the twist—his bear is the problem."] = "Вот тебе странная история, которую я еще не успел проверить. Безумный отшельник в Рифте утверждает, что нынешний Праздник Новой жизни станет последним. Мол, грядет конец света и все такое. В общем, ничего нового.\n\nА странность вот в чем: он считает, что в этом виноват его медведь.",
    ["Pet bear, yes. Seems like the bear's mood determines the fate of each New Life, and right now the bear is miserable. The hermit needs help cheering him up.\n\nThe bear's also … quite large. Hard to miss. Find them by a lake near Skald's Retreat."] = "Да, ручной медведь. Похоже, от его настроения зависит судьба каждого Праздника Новой жизни, а нынче он совсем приуныл. Отшельник просит помочь его развеселить.\n\nМедведь этот… весьма внушительных размеров. Мимо точно не пройдешь. Ищи их обоих у озера возле Приюта скальдов.",
    ["Hermit claims this may be Tamriel's last New Life! Talk to me to learn more!"] = "Некий отшельник заявляет, что этот Праздник Новой жизни может стать для Тамриэля последним! Кому интересно — подходи!",
    ["An empty bottle of bloodwine that still has a strong scent to it."] = "Пустая бутылка из-под кровавого вина, все еще хранящая его запах.",
    ["I met Jahesi once again out in Sentinel. It seems she'd like to continue performing Anseilak for the fallen Yokudan mages until New Life's end. I agreed to travel with her and help with the ritual."] = "Я снова <<player{встретил/встретила}>> Джахеси в Сентинеле. Похоже, она намерена совершать ансейлак для павших йокуданских магов каждый день до конца Праздника Новой жизни. Я <<player{согласился/согласилась}>> составить ей компанию и помочь с ритуалом.",
    ["All right. Let's perform Anseilak."] = "Хорошо. Давай проведем ансейлак.",
    ["Do you need help with something?"] = "Тебе нужна какая-нибудь помощь?",
    ["I need to perform Anseilak for the other Yokudan mages, but my blessing alone won't be enough to make up for the centuries they've been shunned. And most Redguard scowl when I mention them."] = "Мне нужно провести ансейлак для других йокуданских магов, но одного моего благословения не хватит, чтобы возместить многовековое забвение. А большинство редгардов хмурится, стоит мне о них заговорить.",
    ["Until New Life's end. You certainly don't have to trudge through the sand with me every day. But having another blessing would help the mages. And me.\n\nRest assured I'll reward you for your time."] = "До конца Праздника Новой жизни. Конечно, тебе не обязательно каждый день таскаться за мной сквозь пески. Но еще одно благословение очень помогло бы магам. И мне тоже.\n\nБудь <<player{уверен/уверена}>>, я вознагражу тебя за труды.",
    ["Alik'r's winds have reunited us once more, traveler."] = "Ветра Алик’ра вновь свели нас, <<player{путник/путешественница}>>.",
    ["A wet, earthy clump of mud. Caught and reeled from Shadowfen's fishing holes."] = "Комок мокрой грязи. Выловлен на местах для рыбалки в Тенетопи.",
    ["Clump of Mud"] = "Комок грязи",
    ["Shriveled fish scales. Probably the leftovers of a predator's meal."] = "Высохшая рыбья чешуя. Вероятно, остатки обеда какого-то хищника.",
    ["Bundle of Fish Scales"] = "Сверток с рыбьей чешуей",
    ["I don't know what the Worm Cult wants with the Staff of Magnus or Prince Naemon, but it sounds disastrous. Queen Ayrenn, the Dominion, everything is in jeopardy.\n \nI have the beginnings of a plan, but I can't move fast enough with this injury."] = "Понятия не имею, зачем культу Червя понадобились принц Неймон или Посох Магнуса, но сами по себе новости крайне тревожные. Королева Айренн, Доминион, да что там — весь мир в опасности!\n\nЯ знаю, с чего начать, но из-за травмы не смогу двигаться достаточно быстро.",
    ["A Trick to the Doors"] = "Секрет дверей",
    ["What does it hurt to spin some yarn about me dying like a hero? I just want her to remember me with fondness, that's all.\n\nI'm sure she'll pay you for your delivering the news. She has a good heart. Please. Above all else, she needs to know."] = "Кому станет хуже, если ты слегка приукрасишь истину? Я лишь хочу, чтобы у нее осталась обо мне добрая память.\n\nУверен, она заплатит тому, кто принесет весточку — даже плохую. У Намрерас золотое сердце. Пожалуйста, найди ее. Она имеет право знать.",
    ["A carelessly dropped note written by Terinvel. Sirilonwe wants to see it."] = "Написанная Теринвелом записка, которую тот нечаянно обронил. Надо показать ее Сирилонве.",
    ["Rawl'kha's Dragon's Lair"] = "Логово Дракона Рол’ки",
    ["Glenumbra"] = "Гленумбра",
}